def err_say(source, msg):
    """(what happened, what to do) for a recorded fault, or ("", "")."""
    src = (str(source).split() or ["log"])[0].lower()
    m = str(msg or "")
    for _src, _rx, _what, _todo in ERR_SAY:
        if _src and _src != src:
            continue
        try:
            if re.search(_rx, m, re.I):
                return _what, _todo
        except re.error:
            continue
    return "", ""


def _classify_level(msg):
    low = str(msg).lower()
    if re.search(r"\b(error|fail|fatal|exception|traceback|cuda|out of memory|unreachable|refused|denied)\b", low):
        return "ERROR"
    if "warn" in low:
        return "WARN"
    return "ERROR"

def _record_issue(source, msg):
    try:
        m = str(msg).strip()
        mm = re.match(r"^\[[0-9:. -]+\]\s*(\[[^\]]+\]\s*)?(.*)$", m)
        if mm and mm.group(2):
            m = mm.group(2).strip()
        words = m.split()
        text = " ".join(words[:250]) + (" ..." if len(words) > 250 else "")
        if len(text) > 2500:
            text = text[:2500] + " ..."
        title = (m.split(chr(10))[0]).strip()
        if len(title) > 90:
            title = title[:88] + ".."
        typ = (str(source).split() or ["log"])[0].lower()
        lvl = _classify_level(m)
        _what, _todo = err_say(source, m)
        ERR_LOG.append({"ts": time.strftime("%H:%M:%S"), "level": lvl, "type": typ,
                        "source": str(source), "title": title or "(no message)", "text": text,
                        "say": _what, "todo": _todo})
        if len(ERR_LOG) > 250:
            del ERR_LOG[:len(ERR_LOG) - 250]
        ERR_TOTAL[0] += 1
        ERR_BY_TYPE[typ] = ERR_BY_TYPE.get(typ, 0) + 1
        ERR_BY_LEVEL[lvl] = ERR_BY_LEVEL.get(lvl, 0) + 1
    except Exception:
        pass

def api_errors_snapshot(remote=False):
    if remote:
        return {"total": ERR_TOTAL[0], "byType": {}, "byLevel": dict(ERR_BY_LEVEL), "errors": []}
    return {"total": ERR_TOTAL[0], "byType": dict(ERR_BY_TYPE), "byLevel": dict(ERR_BY_LEVEL),
            "sources": dict(ERR_SOURCE_SAY), "errors": list(reversed(ERR_LOG))}
def api_errors_clear(body=None):
    """Empty the collected issues and this session's error log. Host-only."""
    n = ERR_TOTAL[0]
    del ERR_LOG[:]
    ERR_TOTAL[0] = 0
    ERR_BY_TYPE.clear()
    ERR_BY_LEVEL.clear()
    ERRTRACK.clear()          # or a line already scraped from a server log never returns
    path = ERR_FILE[0]
    if path:
        try:
            with open(path, "w", encoding="utf-8") as f:
                f.write("=== %s %s error log - cleared %s ===\n"
                        % (APP_NAME, APP_VER_UI, time.strftime("%Y-%m-%d %H:%M:%S")))
        except OSError:
            pass
    panel_log("[panel] cleared %d issue(s)" % n)
    return {"ok": True, "cleared": n}


_ERR_SEEN = {}                 # message -> times seen this session (p191)
_ERR_SAY_AT = (1, 2, 10, 100, 1000)
AUDIT_COUNT = [0]              # findings the panel filed against its own work (p191)


def audit(msg):
    """The panel checking its own work: a silent empty is filed like a fault. (p191)"""
    AUDIT_COUNT[0] += 1
    log_error("audit", msg)


def log_error(source, msg, record=True):
    # THE SAME FAULT FOURTEEN TIMES IS ONE FAULT. A message seen before is written
    # again only at 2, 10, 100 and 1000 - with its count - and recorded once. A new
    # error file is a new count. (p191)
    if ERR_FILE[0] is None:
        _ERR_SEEN.clear()
    _key = "%s|%s" % (source, str(msg).strip()[:200])
    _n = _ERR_SEEN.get(_key, 0) + 1
    _ERR_SEEN[_key] = _n
    if _n not in _ERR_SAY_AT:
        return
    if _n > 1:
        msg = "%s (x %d)" % (str(msg).strip(), _n)
        record = False
    try:
        if ERR_FILE[0] is None:
            ld = log_dir()
            ERR_FILE[0] = pick_rotating(ld, "error_", 20)
            with open(ERR_FILE[0], "w", encoding="utf-8") as f:
                f.write("=== %s %s error log - session %s ===\n" % (APP_NAME, APP_VER_UI, time.strftime("%Y-%m-%d %H:%M:%S")))
        with open(ERR_FILE[0], "a", encoding="utf-8") as f:
            f.write("[%s] [%s] %s\n" % (time.strftime("%H:%M:%S"), source, str(msg).strip()[:500]))
    except Exception:
        pass
    if record:
        _record_issue(source, msg)

ERRTRACK = {}
def scan_slot_errors(slot_id, label, ld):
    files = sorted(glob.glob(os.path.join(ld, "srv_%s_*.log" % glob.escape(slot_id))),
                   key=os.path.getmtime, reverse=True)
    if not files: return
    path = files[0]
    st = ERRTRACK.setdefault(slot_id, {"path": "", "pos": 0})
    try:
        size = os.path.getsize(path)
        if st["path"] != path:
            st["path"], st["pos"] = path, max(0, size - 65536)
        if size <= st["pos"]:
            st["pos"] = min(st["pos"], size); return
        with open(path, "rb") as f:
            f.seek(st["pos"]); chunk = f.read(size - st["pos"])
        st["pos"] = size
        for line in ANSI_RX.sub("", chunk.decode("utf-8", errors="ignore")).splitlines():
            if line.startswith("==="):
                continue
            if BENIGN_RX.search(line):
                # Not an issue at all, so not in the issue list either: keeping it
                # out of the error FILE was not enough, because the list decides a
                # line's severity from its own words and "failed" is in this one.
                # It stays in the server's raw log, where anyone reading the load
                # sequence will find it in context.
                if "fit" not in BENIGN_SEEN:
                    BENIGN_SEEN.add("fit")
                    panel_log("[slot] llama.cpp could not measure the drafter's "
                              "memory during fitting - expected for a drafter that "
                              "attaches to the target model, and harmless; the "
                              "drafter loads normally afterwards")
                continue
            if ERR_RX.search(line):
                log_error("slot " + label, line)
            elif WARN_RX.search(line):
                _record_issue("slot " + label, line)
    except Exception:
        pass

def panel_log(msg):
    try:
        with open(os.path.join(log_dir(), "panel.log"), "a", encoding="utf-8") as f:
            f.write("[%s] %s\n" % (time.strftime("%Y-%m-%d %H:%M:%S"), msg))
    except Exception:
        pass
    print(msg)

def log_warn(source, msg):
    """Something worth noticing that did not fail.

    log_error() also raises a UI issue, so using it for an observation - a slow state
    read, say - tells the user something is broken when nothing is. A warning goes to
    panel.log, tagged, and raises nothing.
    """
    panel_log("[warn] [%s] %s" % (source, str(msg).strip()[:500]))


# ---------------------------------------------------------------- scanning
PORT_RX = [re.compile(r'"--port"\s*,\s*"(\d+)"'), re.compile(r'--port\s+(\d+)')]
def parse_ps1_model(path):
    try:
        txt = open(path, encoding="utf-8-sig").read()
    except Exception:
        return ""
    def leaf(p):
        # a launcher may be written on either kind of path, whatever we are running on
        return re.split(r"[\\/]", str(p).strip())[-1]
    m = (re.search(r'"-m",\s*"([^"]+\.gguf)"', txt) or re.search(r'"--model",\s*"([^"]+\.gguf)"', txt))
    if m:
        return leaf(m.group(1))
    # named through a variable instead - read it the same way the card does
    v = (parse_launcher_params(txt) or {}).get("model") or ""
    return leaf(v) if v else ""

SAMPLER_KEYS = [("temp", "--temp"), ("top_p", "--top-p"), ("min_p", "--min-p"),
                ("n_predict", "--n-predict"),
                ("top_k", "--top-k"), ("n_sigma", "--top-n-sigma"), ("typ_p", "--typical"),
                ("xtc_p", "--xtc-probability"), ("xtc_t", "--xtc-threshold"),
                ("dry", "--dry-multiplier"), ("freq", "--frequency-penalty"), ("pres", "--presence-penalty")]

# Per-provider sampler fields the proxy observes in each request body and can override.
# Maps our short key -> the JSON field name llama.cpp / SkyrimNet uses in the request.
PROXY_SAMPLER_FIELDS = {"temp": "temperature", "top_p": "top_p", "min_p": "min_p",
                        "top_k": "top_k", "n_sigma": "top_n_sigma", "typ_p": "typical_p",
                        "xtc_p": "xtc_probability", "xtc_t": "xtc_threshold",
                        "dry": "dry_multiplier", "freq": "frequency_penalty", "pres": "presence_penalty",
                        # DRY is four dials, not one. The chip has always been
                        # --dry-multiplier alone, which is the switch; the other
                        # three shape what it penalises and how far back it
                        # looks. Blank leaves each out of the request. (p89)
                        "dry_base": "dry_base",
                        "dry_allowed": "dry_allowed_length",
                        "dry_last_n": "dry_penalty_last_n"}

def _num_str(v):
    """normalize a numeric sampler value to a short display string."""
    try:
        f = float(v)
        return ("%g" % f)
    except Exception:
        return str(v)[:10]
def parse_ps1_samplers(path):
    out = {}
    try:
        txt = open(path, encoding="utf-8-sig").read()
    except Exception:
        return out
    m = re.search(r"llamaArgs\s*=\s*@\(", txt, re.I)
    if m:
        end = txt.find("\n)", m.end())
        region = txt[m.end():end if end > 0 else len(txt)]
    else:
        region = txt
    for key, flag in SAMPLER_KEYS:
        mm = re.search("[\"']%s[\"']\\s*,\\s*[\"']([^\"']+)[\"']" % re.escape(flag), region)
        if mm:
            out[key] = mm.group(1)
    if "n_predict" not in out:
        mm = re.search("[\"']-n[\"']\\s*,\\s*[\"']([0-9]+)[\"']", region)
        if mm:
            out["n_predict"] = mm.group(1)
    return out

def _latest_srv_log(slot_id, ld):
    files = sorted(glob.glob(os.path.join(ld, "srv_%s_*.log" % slot_id)), key=os.path.getmtime)
    return files[-1] if files else None

SAMPLER_NAMES = ("penalties", "dry", "top_k", "top_p", "min_p", "temp", "temperature")

def parse_log_samplers(slot_id, ld):
    """live sampler values: pair the numbers row to the names row by column position."""
    try:
        f = _latest_srv_log(slot_id, ld)
        if not f:
            return {}
        with open(f, "rb") as fh:
            fh.seek(max(0, os.path.getsize(f) - 40000))
            tail = fh.read().decode("utf-8", "replace")
        i = tail.rfind("Sampler chain")
        if i < 0:
            return {}
        lines = tail[i:].split(chr(10))[1:4]
        name_line = num_line = None
        for j, ln in enumerate(lines):
            if sum(1 for n in SAMPLER_NAMES if n in ln) >= 3:
                name_line = ln
                num_line = lines[j + 1] if j + 1 < len(lines) else ""
                break
        if name_line is None:
            return {}
        npos = [(m.start(), m.group(0)) for m in re.finditer("|".join(SAMPLER_NAMES[:6]), name_line)]
        out = {}
        for m in re.finditer(r"[0-9]+(?:\.[0-9]+)?", num_line):
            p = m.start()
            best = min(npos, key=lambda nv: abs(nv[0] - p)) if npos else None
            if best:
                key = "temp" if best[1] == "temperature" else best[1]
                out[key] = m.group(0)
        out.pop("penalties", None)
        return out
    except Exception:
        return {}

_PS1_REASON = {}                # path -> (mtime, size, value); the file is on the
_PS1_REASON_LOCK = threading.Lock()   # hot path via PTI, so it is read once per edit


def slot_reasoning(slot):
    """What the server card's Reasoning dial says, cached against the launcher file.

    `--reasoning off` tells the SERVER not to emit thinking. Some models ignore the
    flag and only honour the per-request kwarg, so a slot set to off now forces the
    request side off as well: both, because builds disagree about which they read.
    """
    path = (slot or {}).get("script") or ""
    if not path:
        return ""
    try:
        s = os.stat(path)
        sig = (s.st_mtime_ns, s.st_size)
    except OSError:
        return ""
    with _PS1_REASON_LOCK:
        hit = _PS1_REASON.get(path)
        if hit and hit[0] == sig:
            return hit[1]
    val = parse_ps1_reasoning(path)
    with _PS1_REASON_LOCK:
        _PS1_REASON[path] = (sig, val)
    return val


def parse_ps1_reasoning(path):
    try:
        txt = open(path, encoding="utf-8-sig").read()
    except Exception:
        return ""
    m = re.search("[\"']--reasoning[\"']\\s*,\\s*[\"'](on|off)[\"']", txt, re.I)
    if m:
        return m.group(1).lower()
    m = re.search(r"--reasoning\s+(on|off)", txt, re.I)
    return m.group(1).lower() if m else ""

def parse_log_reasoning(slot_id, ld):
    """'on' / 'off' / '' from the launcher banner in the newest srv log."""
    try:
        f = _latest_srv_log(slot_id, ld)
        if not f:
            return ""
        head = open(f, "rb").read(4096).decode("utf-8", "replace")
        m = re.search(r"reasoning (ON|OFF)", head, re.I)
        return m.group(1).lower() if m else ""
    except Exception:
        return ""

def _profile_snapshot(cfg):
    """One profile now covers the whole setup - wiring, server parameters and settings -
    so there is no longer a separate notion of a server profile vs a provider profile."""
    return {"gpus": [{"id": g.get("id"), "enabled": g.get("enabled", True)} for g in cfg.get("gpus", [])],
            "slots": [{"id": s.get("id"), "gpuId": s.get("gpuId", ""), "label": s.get("label", ""),
                       "port": s.get("port"), "params": json.loads(json.dumps(s.get("params", {}) or {})),
                       "providers": json.loads(json.dumps(s.get("providers", []) or []))}
                      for s in cfg.get("slots", [])],
            "unallocatedProviders": json.loads(json.dumps(cfg.get("unallocatedProviders", []) or [])),
            "settings": {k: cfg.get("settings", {}).get(k, "") for k in ("panelIp", "remoteIp")}}

PROFILE_DIR = os.path.join(STACK, "profiles")

def _profile_file(name):
    safe = re.sub(r"[^A-Za-z0-9._ -]", "_", str(name)).strip()
    return os.path.join(PROFILE_DIR, safe + ".json") if safe else ""

def _profile_names():
    try:
        return sorted(f[:-5] for f in os.listdir(PROFILE_DIR) if f.lower().endswith(".json"))
    except Exception:
        return []

def _profiles_migrate(cfg):
    """Move any profile still living inside the config out into its own file, once."""
    old = cfg.get("profiles") or {}
    if not old:
        return False
    try:
        os.makedirs(PROFILE_DIR, exist_ok=True)
    except Exception:
        return False
    moved = 0
    for name, prof in old.items():
        p = _profile_file(name)
        if p and not os.path.exists(p):
            try:
                with open(p, "w", encoding="utf-8") as f:
                    json.dump(prof, f, indent=2)
                moved += 1
            except Exception:
                pass
    cfg["profiles"] = {}
    if moved:
        panel_log("[panel] moved %d profile(s) into %s" % (moved, PROFILE_DIR))
    return True

def _profile_read(name):
    p = _profile_file(name)
    if not p or not os.path.isfile(p):
        return None
    try:
        with open(p, encoding="utf-8") as f:
            return json.load(f)
    except Exception:
        return None

def api_profile_save(body):
    name = str(body.get("name", "")).strip()[:40]
    if not name:
        return {"error": "profile needs a name"}
    cfg = load_config()
    if _profiles_migrate(cfg):
        save_config(cfg)
    p = _profile_file(name)
    if not p:
        return {"error": "that name cannot be used for a file"}
    try:
        os.makedirs(PROFILE_DIR, exist_ok=True)
        with open(p, "w", encoding="utf-8") as f:
            json.dump(_profile_snapshot(cfg), f, indent=2)
        cfg["settings"]["activeProfile"] = name
        save_config(cfg)
    except Exception as e:
        return {"error": "cannot write the profile: %s" % e}
    panel_log("[panel] profile saved: %s" % p)
    return {"ok": True, "profiles": _profile_names()}

def api_profile_load(body):
    name = str(body.get("name", "")).strip()
    cfg = load_config()
    if _profiles_migrate(cfg):
        save_config(cfg)
    prof = _profile_read(name)
    if not prof:
        return {"error": "unknown profile"}
    ge = {g["id"]: g.get("enabled", True) for g in prof.get("gpus", [])}
    for g in cfg.get("gpus", []):
        if g.get("id") in ge:
            g["enabled"] = ge[g.get("id")]
    ps = {s["id"]: s for s in prof.get("slots", [])}
    for s in cfg.get("slots", []):
        if s.get("id") in ps:
            s["gpuId"] = ps[s["id"]].get("gpuId", "")
            s["providers"] = json.loads(json.dumps(ps[s["id"]].get("providers", [])))
    for k, v in (prof.get("settings") or {}).items():
        if v:
            cfg["settings"][k] = v
    cfg["settings"]["activeProfile"] = name
    save_config(cfg)
    PROXY.sync()
    panel_log("[panel] profile loaded: %s" % name)
    return {"ok": True}

def api_profile_delete(body):
    name = str(body.get("name", "")).strip()
    cfg = load_config()
    if _profiles_migrate(cfg):
        save_config(cfg)
    p = _profile_file(name)
    if p and os.path.isfile(p):
        try:
            os.remove(p)
        except Exception as e:
            return {"error": "cannot delete the profile: %s" % e}
        panel_log("[panel] profile deleted: %s" % name)
        return {"ok": True, "profiles": _profile_names()}
    return {"error": "unknown profile"}

def api_helper_skip(body):
    cfg = load_config()
    try:
        step = int(body.get("step"))
    except Exception:
        return {"error": "bad step"}
    sk = cfg["settings"].setdefault("helperSkipped", [])
    if body.get("on"):
        if step not in sk:
            sk.append(step)
    else:
        cfg["settings"]["helperSkipped"] = [x for x in sk if x != step]
    save_config(cfg)
    return {"ok": True}

def _log_sources(cfg):
    ld = log_dir(cfg)
    out = []
    seen = set()
    for d in (ld, STACK):
        try:
            for f in sorted(os.listdir(d)):
                if not f.endswith(".log") or f in seen:
                    continue
                p = os.path.join(d, f)
                try:
                    st = os.stat(p)
                    out.append({"name": f, "size": st.st_size, "mtime": time.strftime("%Y-%m-%d %H:%M:%S", time.localtime(st.st_mtime)), "dir": d})
                    seen.add(f)
                except Exception:
                    pass
        except Exception:
            pass
    return out

def api_logs_meta(body):
    cfg = load_config()
    files = _log_sources(cfg)
    entries = []
    def add(path, deflevel):
        try:
            lines = open(path, encoding="utf-8", errors="replace").read().splitlines()[-500:]
        except Exception:
            return
        for ln in lines:
            if not ln.strip():
                continue
            lvl = deflevel
            low = ln.lower()
            if "error" in low or "fail" in low or "traceback" in low:
                lvl = "ERROR"
            elif "warn" in low:
                lvl = "WARN"
            m = re.match(r"\[([0-9: -]+)\]\s*(\[[^\]]+\])?\s*(.*)", ln)
            entries.append({"level": lvl, "time": (m.group(1) if m else ""), "tag": ((m.group(2) or "").strip("[]") if m else ""), "msg": (m.group(3) if m else ln)})
    err = os.path.join(STACK, "error_1.log")
    for f in sorted(os.listdir(STACK)):
        if f.startswith("error_") and f.endswith(".log"):
            err = os.path.join(STACK, f)
    add(err, "ERROR")
    add(os.path.join(STACK, "panel.log"), "INFO")
    entries.reverse()
    counts = {"ERROR": 0, "WARN": 0, "INFO": 0}
    for e in entries:
        counts[e["level"]] = counts.get(e["level"], 0) + 1
    return {"files": files, "entries": entries[:400], "counts": counts, "dir": log_dir(cfg)}

def api_log_read(body):
    name = os.path.basename(str(body.get("name", "")))
    cfg = load_config()
    cand = [os.path.join(log_dir(cfg), name), os.path.join(STACK, name)]
    for p in cand:
        if os.path.isfile(p):
            try:
                data = open(p, "rb").read()
                tail = data[-200000:]
                txt = tail.decode("utf-8", errors="replace")
                if len(data) > len(tail):
                    txt = "... (showing last 200 KB of %d KB) ...\n" % (len(data) // 1024) + txt
                return {"ok": True, "name": name, "text": txt}
            except Exception as e:
                return {"error": str(e)}
    return {"error": "not found"}

def api_logs_clear(body):
    ERR_LOG.clear(); ERR_TOTAL[0] = 0; ERR_BY_TYPE.clear(); ERR_BY_LEVEL.clear()
    n = 0
    for f in os.listdir(STACK):
        if f.startswith("error_") and f.endswith(".log"):
            try:
                open(os.path.join(STACK, f), "w").close()
                n += 1
            except Exception:
                pass
    return {"ok": True, "cleared": n}

def api_path_check(body):
    """Does a folder actually hold what the panel needs from it?"""
    p = str(body.get("path", "")).strip()
    kind = str(body.get("kind") or "llamacppPath")
    if not p or not os.path.isdir(p):
        return {"ok": False}
    if kind == "modelsDir":
        # models are often filed in per-model subfolders, so look a little way down,
        # but stop at the first hit and do not walk an entire drive
        try:
            root_depth = p.rstrip("\\/").count(os.sep)
            for root, dirs, files in os.walk(p):
                if any(f.lower().endswith(".gguf") for f in files):
                    return {"ok": True}
                if root.count(os.sep) - root_depth >= 2:
                    dirs[:] = []
        except Exception:
            pass
        return {"ok": False}
    if kind in ("logDir", "yamlOutDir", "outputDir"):
        return {"ok": True}          # written to, not read from: existing is all it needs
    if kind == "launcherDir":
        try:
            return {"ok": any(f.lower().endswith(".ps1") for f in os.listdir(p))}
        except Exception:
            return {"ok": False}
    if kind == "ttsAcppDir":
        exe = find_acpp_exe(p)
        return {"ok": bool(exe), "exe": exe}
    return {"ok": os.path.isfile(os.path.join(p, "llama-server.exe"))}

def debug_report():
    """A short account of this build and this machine's setup, meant to be shared.

    Deliberately narrow: enough to tell what is configured and what has gone wrong,
    with nothing in it that identifies you. No paths, no IP addresses, no GPU serial
    numbers, no model filenames - a folder is reported as set or not set, and a model
    as what kind of model it is. What matters for a bug report is the shape of the
    setup, not its contents.
    """
    cfg = load_config()
    st = cfg.get("settings", {}) or {}
    def folder(key, kind="llamacppPath"):
        p = (st.get(key) or "").strip()
        if not p:
            return "not set"
        return "ok" if api_path_check({"path": p, "kind": key}).get("ok") else "set, but nothing expected found in it"
    slots = cfg.get("slots", []) or []
    lines = []
    A = lines.append
    A("PandorumLLM %s debug report" % APP_VER_UI)
    A("generated %s" % time.strftime("%Y-%m-%d %H:%M:%S"))
    A("running file %s" % BUILD_ID.get("path", "?"))
    A("build %s, %s KB, modified %s" % (BUILD_ID.get("sha", "?"), BUILD_ID.get("kb", 0), BUILD_ID.get("mtime", "?")))
    A("")
    A("-- this machine ------------------------------------------------")
    A("  windows            : %s" % ("yes" if os.name == "nt" else "no (%s)" % sys.platform))
    A("  python             : %s" % sys.version.split()[0])
    A("  panel port         : %s" % PORT)
    # kept for diagnostics only. The panel has not asked for elevation since v3.72
    # patch15 and does not need it: high ports, its own folder, and it only signals
    # processes it started itself.
    A("  running elevated   : %s" % is_admin())
    A("")
    A("-- folders -----------------------------------------------------")
    for key, label in (("llamacppPath", "llama.cpp"), ("modelsDir", "models"),
                       ("launcherDir", "ps1 launchers"), ("logDir", "logs"),
                       ("yamlOutDir", "providers.yaml out")):
        A("  %-18s : %s" % (label, folder(key)))
    A("")
    A("-- setup -------------------------------------------------------")
    A("  mode               : %s" % ("1 PC" if st.get("onePC", True) else "2 PC"))
    A("  panel IP set       : %s" % bool((st.get("panelIp") or "").strip()))
    A("  remote IP set      : %s" % bool((st.get("remoteIp") or "").strip()))
    A("  yaml generated     : %s" % bool(st.get("yamlGenerated")))
    A("  theme              : %s" % (st.get("themeName") or "default"))
    A("")
    A("-- graphics cards ----------------------------------------------")
    gp = cfg.get("gpus", []) or []
    A("  detected           : %d" % len(gp))
    for i, g in enumerate(gp):
        A("    card %d           : %s, %s" % (i, g.get("name", "?"),
                                              "enabled" if g.get("enabled", True) else "disabled"))
    A("")
    A("-- servers -----------------------------------------------------")
    A("  configured         : %d" % len(slots))
    # requests open on each upstream right now. The proxy has counted this on every
    # forward since patch98 and NOTHING read it - the counter was paid for and
    # thrown away. It belongs here: "one server is holding four" is the first thing
    # a slow-fleet report needs to say. (patch184)
    _open = [(s.get("port"), PROXY.busy(s.get("port") or 0)) for s in slots]
    if any(n for _p, n in _open):
        A("  requests open now  : %s" % ", ".join("port %s: %d" % (p, n)
                                                  for p, n in _open if n))
    for s in slots:
        p = s.get("params", {}) or {}
        mdl = (p.get("model") or "").strip()
        kind = model_kind(mdl) if mdl and os.path.isfile(mdl) else ("set, file missing" if mdl else "none")
        A("    port %-6s      : model %s, on a GPU: %s, launcher built: %s, %s"
          % (s.get("port", "?"), kind, bool(s.get("gpuId")),
             bool(s.get("script")) and os.path.isfile(s.get("script") or ""),
             slot_status(s.get("port")).get("state", "?")))
        # only the runtime settings, and only where they differ from the default -
        # a list of defaults tells nobody anything and buries what does not
        d = param_defaults()
        changed = [(k, str(p.get(k))) for (k, _l, _ki, _dv, _o, _f, _r) in SERVER_PARAMS
                   if str(p.get(k, "")).strip() not in ("", str(d.get(k, "")))]
        if changed:
            A("        changed from default: " + ", ".join("%s=%s" % kv for kv in changed))
        if (p.get("vision") or "N/A") not in ("", "N/A", "Disabled"):
            A("        vision projector: yes")
        if (p.get("draft") or "N/A") not in ("", "N/A", "Disabled"):
            A("        draft model     : yes")
        if (p.get("custom") or "").strip():
            A("        launcher        : hand-edited")
        A("        providers       : %d" % len(s.get("providers", []) or []))
    A("")
    A("-- port behaviour ----------------------------------------------")
    A("  a closed port should refuse at once; waiting means something filtered it.")
    _ctl = _free_port()
    _rows = ([("control (closed)", _ctl)] if _ctl else []) + [("panel (listening)", PORT)]
    _rows += [("server " + str(x.get("port") or "?"), x.get("port")) for x in slots if x.get("port")]
    _odd = False
    for _lab, _pt in _rows:
        _v, _ms, _rc = _port_verdict(_pt)
        A("  %-18s : %s in %dms%s" % (_lab, _v, _ms, (" (code %d)" % _rc) if _rc > 0 else ""))
        if _v == "no answer":
            _odd = True
    if _odd:
        A("  a port that neither answers nor refuses is being intercepted - look at")
        A("  third-party antivirus or firewall, and at VPN or container filter drivers")
    A("")

    A("-- recent problems ---------------------------------------------")
    A("  total this session : %d" % ERR_TOTAL[0])
    for kind, count in sorted(ERR_BY_TYPE.items(), key=lambda x: -x[1]):
        A("    %-16s : %d" % (kind, count))
    recent = ERR_LOG[-20:]
    if not recent:
        A("  nothing recorded this session")
    for it in recent:
        A("  [%s] [%s] %s" % (it.get("ts", "?"), it.get("source", "?"), str(it.get("title", ""))[:150]))
    return "\n".join(lines) + "\n"

def _st_gguf_bytes(arch="selftest", cut=False):
    """A minimal GGUF header the panel's own reader accepts: magic, version 3, no
    tensors, three keys. With cut=True the second key is replaced by zeros - the
    way Windows pre-allocates a copy still being written. (p192)"""
    def s(x):
        b = x.encode("utf-8"); return len(b).to_bytes(8, "little") + b
    kv = s("general.architecture") + (8).to_bytes(4, "little") + s(arch)
    kv2 = s("general.name") + (8).to_bytes(4, "little") + s("Self Test")
    kv3 = s("selftest.block_count") + (4).to_bytes(4, "little") + (2).to_bytes(4, "little")
    head = b"GGUF" + (3).to_bytes(4, "little") + (0).to_bytes(8, "little") + (3).to_bytes(8, "little")
    if cut:
        return head + kv + b"\x00" * 4096
    return head + kv + kv2 + kv3 + b"\x00" * 64


def _st_mask(p):
    """A path in the report with the user's profile folder shortened to ~ - the
    report is meant to be pasted into a bug, and the account name is nobody's
    business (v3.80)."""
    try:
        home = os.path.expanduser("~")
        p = str(p or "")
        return "~" + p[len(home):] if home and p.lower().startswith(home.lower()) else p
    except Exception:
        return str(p or "")


def selftest_busy():
    """Why the self-test must wait, or ''."""
    try:
        if _MODELS_SCAN.get("running"):
            return "a model scan is running"
        p = os.path.join(log_dir(), "update-result.json")
        if os.path.exists(p):
            with open(p, "r", encoding="utf-8") as f:
                u = json.load(f)
            if str(u.get("state", "")) in ("running", "swapping") and time.time() - float(u.get("at", 0) or 0) < 600:
                return "an update is in progress"
    except Exception:
        pass                # nothing readable means nothing in the way
    return ""


def selftest_run(cfg=None):
    """THE PANEL EXERCISING ITS OWN MECHANISMS ON THIS MACHINE - the ones the
    gate cannot run where it runs. Every probe works in a scratch folder under
    the logs and leaves nothing behind; it reads real things only where reading
    changes nothing (nvidia-smi's query, PowerShell's version). A failure that
    only a panel fault explains is filed under audit as well. (p192)"""
    why = selftest_busy()
    if why:
        return {"error": "not now: %s - try again when it has finished" % why}
    ld = log_dir()
    scratch = os.path.join(ld, "selftest")
    shutil.rmtree(scratch, ignore_errors=True)
    os.makedirs(scratch, exist_ok=True)
    rows = []
    win = os.name == "nt"
    def row(name, status, note=""):
        rows.append((name, status, note))
    # 1. the folder watcher
    if not win:
        row("folder watcher", "skip", "not run on this OS (ReadDirectoryChangesW)")
    else:
        try:
            hold = {}
            _MODELS_MOVED["at"] = 0.0
            th = threading.Thread(target=_models_watch_folder, args=(scratch, hold), daemon=True)
            th.start(); time.sleep(0.4)
            with open(os.path.join(scratch, "watch.gguf"), "wb") as f:
                f.write(_st_gguf_bytes())
            t0 = time.time()
            while time.time() - t0 < 5.0 and not _MODELS_MOVED["at"]:
                time.sleep(0.1)
            fired = bool(_MODELS_MOVED["at"])
            _MODELS_MOVED["at"] = 0.0; _MODELS_MOVED["sig"] = None
            # end the watch cooperatively: flag it, wake it with a touch, wait for it
            hold["stop"] = True
            try:
                with open(os.path.join(scratch, "wake.tmp"), "wb") as f:
                    f.write(b"x")
            except Exception:
                pass            # the thread is a daemon; the folder is scratch
            th.join(3.0)
            if fired:
                row("folder watcher", "pass", "woke within %.1fs of a file landing" % (time.time() - t0))
            else:
                row("folder watcher", "fail", "did not wake within 5s of a file landing")
                audit("self-test: the folder watcher did not wake for a file landing in its folder")
        except Exception as e:
            row("folder watcher", "fail", str(e)[:120])
    # 2. the busy file
    if not win:
        row("busy file", "skip", "not run on this OS (CreateFileW, no sharing)")
    else:
        try:
            p = os.path.join(scratch, "held.bin")
            with open(p, "wb") as f:
                f.write(b"x" * 64)
            with open(p, "rb") as held:
                busy = file_in_use(p)
            free = file_in_use(p)
            if busy is True and not free:
                row("busy file", "pass", "held reads busy, released reads free")
            else:
                row("busy file", "fail", "held=%r released=%r" % (busy, free))
                audit("self-test: file_in_use answered held=%r released=%r for a file the panel itself held" % (busy, free))
        except Exception as e:
            row("busy file", "fail", str(e)[:120])
    # 3. a copy in progress
    try:
        p = os.path.join(scratch, "copying.gguf")
        with open(p, "wb") as f:
            f.write(_st_gguf_bytes(cut=True))
        a = gguf_meta(p)
        with open(p, "wb") as f:
            f.write(_st_gguf_bytes())
        b = gguf_meta(p)
        if not a.get("_hdrDone") and b.get("_hdrDone") and str(b.get("general.architecture", "")).lower() == "selftest":
            row("copy in progress", "pass", "a zero-filled tail reads as unfinished; the finished file reads its architecture")
        else:
            row("copy in progress", "fail", "cut=%r done=%r arch=%r" % (a.get("_hdrDone"), b.get("_hdrDone"), b.get("general.architecture")))
            audit("self-test: the GGUF reader answered cut=%r done=%r for a copy in progress" % (a.get("_hdrDone"), b.get("_hdrDone")))
    except Exception as e:
        row("copy in progress", "fail", str(e)[:120])
    # 4. settings saved under contention, to a scratch copy
    try:
        sp = os.path.join(scratch, "fleet-config.json")
        base = dict((cfg or load_config()))
        errs = []
        def hammer():
            for i in range(50):
                try:
                    save_config(base, path=sp)
                except Exception as e:
                    errs.append(str(e)[:80])
        ths = [threading.Thread(target=hammer) for _ in range(2)]
        for th in ths: th.start()
        for th in ths: th.join(30)
        with open(sp, "r", encoding="utf-8") as f:
            json.load(f)
        if errs:
            row("settings save under contention", "fail", "%d of 100 saves failed: %s" % (len(errs), errs[0]))
        else:
            row("settings save under contention", "pass", "100 saves from two threads, the file whole")
    except Exception as e:
        row("settings save under contention", "fail", str(e)[:120])
    # 5. log rotation with a file held
    try:
        rd = os.path.join(scratch, "rot"); os.makedirs(rd, exist_ok=True)
        for i in range(20):
            with open(os.path.join(rd, "error_%d.log" % i), "w") as f:
                f.write("x")
        with open(os.path.join(rd, "error_0.log"), "r") as held:
            picked = pick_rotating(rd, "error_", 20)
            with open(picked, "w", encoding="utf-8") as f:
                f.write("picked\n")
        row("log rotation", "pass", "picked %s with another held open" % os.path.basename(picked))
    except Exception as e:
        row("log rotation", "fail", str(e)[:120])
    # 6. the DLL swap strategies, on a scratch copy
    if not win:
        row("DLL swap", "skip", "not run on this OS")
    else:
        try:
            old = os.path.join(scratch, "held.dll"); new = os.path.join(scratch, "new.dll")
            with open(old, "wb") as f: f.write(b"old" * 100)
            with open(new, "wb") as f: f.write(b"new" * 100)
            got = []
            with open(old, "rb") as held:
                try:
                    os.replace(new, old); got.append("replace-over-held: worked")
                except OSError as e:
                    got.append("replace-over-held: refused (%s)" % (getattr(e, "winerror", "") or "OSError"))
                try:
                    os.rename(old, old + ".old"); got.append("rename-away-held: worked")
                except OSError as e:
                    got.append("rename-away-held: refused (%s)" % (getattr(e, "winerror", "") or "OSError"))
            row("DLL swap", "pass", "; ".join(got))
        except Exception as e:
            row("DLL swap", "fail", str(e)[:120])
    # 7. the audio folder
    try:
        d = TTSW.dir(); p = os.path.join(d, "selftest-%d.wav" % os.getpid())
        data = bytes(range(256)) * 8
        with wave.open(p, "wb") as w:
            w.setnchannels(1); w.setsampwidth(2); w.setframerate(24000); w.writeframes(data)
        with wave.open(p, "rb") as w:
            back = w.readframes(w.getnframes())
        os.remove(p)
        if back == data:
            row("audio folder", "pass", "%s: written and read back whole" % _st_mask(d))
        else:
            row("audio folder", "fail", "%s: read back differs" % _st_mask(d))
    except Exception as e:
        row("audio folder", "fail", str(e)[:120])
    # 8. a name with accents
    try:
        p = os.path.join(scratch, "\u00c6ther-caf\u00e9.gguf")
        with open(p, "wb") as f:
            f.write(_st_gguf_bytes())
        m = gguf_meta(p)
        if str(m.get("general.architecture", "")).lower() == "selftest":
            row("accented file name", "pass", "read through its architecture")
        else:
            row("accented file name", "fail", "arch=%r" % m.get("general.architecture"))
    except Exception as e:
        row("accented file name", "fail", str(e)[:120])
    # 9. PowerShell
    if not win:
        row("PowerShell", "skip", "not run on this OS")
    else:
        try:
            r = subprocess.run(["powershell", "-NoProfile", "-Command", "$PSVersionTable.PSVersion.ToString()"],
                               capture_output=True, text=True, timeout=15, **NOWIN)
            v = (r.stdout or "").strip()
            row("PowerShell", "pass" if r.returncode == 0 and v else "fail", v or (r.stderr or "")[:80])
        except Exception as e:
            row("PowerShell", "fail", str(e)[:120])
    # 10. the GPU clock query
    try:
        r = subprocess.run(["nvidia-smi", "--query-gpu=clocks.sm", "--format=csv,noheader"],
                           capture_output=True, text=True, timeout=15, **NOWIN)
        v = (r.stdout or "").strip().replace("\n", "; ")
        row("GPU clock query", "pass" if r.returncode == 0 and v else "fail", v or (r.stderr or "")[:80])
    except FileNotFoundError:
        row("GPU clock query", "skip", "nvidia-smi not found")
    except Exception as e:
        row("GPU clock query", "fail", str(e)[:120])
    shutil.rmtree(scratch, ignore_errors=True)
    stamp = time.strftime("%Y%m%d-%H%M%S")
    text = "%s %s self-test - %s - %s\n" % (APP_NAME, APP_VER_UI, stamp, "Windows" if win else os.name)
    text += "\n".join("%-32s %-5s %s" % r for r in rows)
    out = ""
    try:
        out = os.path.join(ld, "selftest-%s.txt" % stamp)
        with open(out, "w", encoding="utf-8") as f:
            f.write(text + "\n")
    except Exception:
        out = ""            # the report is still returned
    return {"rows": rows, "text": text, "file": out,
            "passed": sum(1 for r in rows if r[1] == "pass"), "failed": sum(1 for r in rows if r[1] == "fail"),
            "skipped": sum(1 for r in rows if r[1] == "skip")}


_SELFTEST = {"thread": None, "result": None, "started": 0.0}


def api_selftest(body):
    """Start the self-test in a thread of its own and answer at once: a probe that
    blocks must never hold a request open - the page gates every redraw on the
    requests it has out (p192 froze the whole page that way). (p193)"""
    why = selftest_busy()
    if why:
        return {"error": "not now: %s - try again when it has finished" % why}
    th = _SELFTEST.get("thread")
    if th is not None and th.is_alive():
        return {"started": True, "running": True}
    _SELFTEST["result"] = None
    _SELFTEST["started"] = time.time()
    def run():
        try:
            _SELFTEST["result"] = selftest_run()
        except Exception as e:
            _SELFTEST["result"] = {"error": "the self-test itself failed: %s" % str(e)[:160]}
    th = threading.Thread(target=run, daemon=True, name="selftest")
    _SELFTEST["thread"] = th
    th.start()
    return {"started": True, "running": True}


def api_selftest_status(body):
    th = _SELFTEST.get("thread")
    if th is not None and th.is_alive():
        return {"running": True, "secs": round(time.time() - float(_SELFTEST.get("started") or time.time()), 1)}
    r = _SELFTEST.get("result")
    if r is None:
        return {"running": False, "error": "no self-test has run"}
    return dict(r, running=False)


def api_diagnose(body):
    """The session read back the way a fault is found by hand: records against
    references, rows against ids, written rows against voiced lines, the TTS
    numbers, the errors by source. One table, one copyable text. (p191)"""
    ld = log_dir()
    sess = str(getattr(PROXY, "session", "") or SESSION_STAMP)
    def read(name):
        try:
            with open(os.path.join(ld, name), "r", encoding="utf-8", errors="replace") as f:
                return f.read()
        except Exception:
            return ""
    dash = read("%s_dashboard.log" % sess).splitlines()
    tts = read("%s_tts.log" % sess).splitlines()
    recs = []
    for l in read("%s_payloads.jsonl" % sess).splitlines():
        try:
            recs.append(json.loads(l))
        except Exception:
            pass            # a torn line at the file's end
    ids = set(r.get("id") for r in recs)
    speech = [r for r in recs if r.get("title") in SPEECH_TITLES]
    rows_with_id = sum(1 for l in dash if re.search(r"\u27e6\d+\u27e7\s*$", l))
    refs = [int(m.group(1)) for l in tts for m in [re.search(r"\u27e8dlg:(\d+)\u27e9", l)] if m and "\u3030\ufe0f" in l]
    resolved = sum(1 for p in refs if p in ids)
    short = sum(1 for p in refs if p not in ids and (p + 1) in ids)
    written = sum(1 for l in dash if "\u3030\ufe0f" in l and "\u27ea" not in l)
    voiced = sum(1 for l in tts if "\u3030\ufe0f" in l)
    realtime = sum(1 for l in tts if "x realtime" in l)
    tries = {"1": 0, "2": 0, "3+": 0}
    try:
        for row in csv.DictReader(open(os.path.join(ld, "tts-timing.csv"), encoding="utf-8", errors="replace")):
            if not str(row.get("at", "")).startswith(time.strftime("%Y-%m-%d")):
                continue
            k = str(row.get("tries", "1")); tries["3+" if k not in ("1", "2") else k] += 1
    except Exception:
        pass                # no timing file yet: the row says so
    eoc_total = eoc_unclean = 0
    try:
        for e in json.load(open(os.path.join(ld, "eoc-events.json"), encoding="utf-8")):
            eoc_total += 1
            if not e.get("ends_clean", True):
                eoc_unclean += 1
    except Exception:
        pass                # no EOC file yet: the row says so
    errs = {}
    try:
        for l in open(ERR_FILE[0], encoding="utf-8", errors="replace") if ERR_FILE[0] else []:
            m = re.match(r"^\[[0-9:]+\] \[([^\]]+)\]", l)
            if m:
                errs[m.group(1)] = errs.get(m.group(1), 0) + 1
    except Exception:
        pass                # no error file yet: the row says none
    total_tries = sum(tries.values())
    rows = [
        ("records kept", "%d (%d Dialogue/Combat)" % (len(recs), len(speech)), ""),
        ("record rows wearing their id", "%d of %d" % (rows_with_id, len(recs)), "" if rows_with_id >= len(recs) else "a row without its id cannot anchor spoken lines"),
        ("references written by spoken lines", "%d" % len(refs), ""),
        ("references naming a kept record", "%d of %d" % (resolved, len(refs)), "" if resolved == len(refs) else ("%d one short of their record" % short if short else "some name no record")),
        ("spoken rows written by records", "%d" % written, "what the replies said"),
        ("spoken lines voiced by TTS", "%d (%d with a realtime figure)" % (voiced, realtime), ""),
        ("TTS first-try rate", ("%d%% of %d" % (100 * tries["1"] // total_tries, total_tries)) if total_tries else "no lines today", "second try %d, third or more %d" % (tries["2"], tries["3+"])),
        ("EOC events not ending clean", "%d of %d" % (eoc_unclean, eoc_total), ""),
        ("errors filed, by source", ", ".join("%s %d" % kv for kv in sorted(errs.items())) or "none", ""),
        ("audit findings this session", "%d" % AUDIT_COUNT[0], "the panel's own checks; see Errors"),
        ("providers hidden by the terminal filter", (lambda h: "%d (%s)" % (len(h), ", ".join(h)[:60]) if h else "none")([x for x in str((load_config().get("settings", {}) or {}).get("termHideProv", "")).split(",") if x.strip()]), "the Providers popover on the Proxy terminal"),
    ]
    text = "\n".join("%-38s %-28s %s" % r for r in rows)
    return {"session": sess, "rows": rows, "text": "%s %s - session %s\n%s" % (APP_NAME, APP_VER_UI, sess, text)}


