def arch_label(arch):
    """A family name for an architecture, or the architecture itself when it is one
    the panel has not been taught - never a guess from the file's name."""
    a = str(arch or "").strip().lower()
    if not a:
        return ""
    if a in MODEL_ARCH_NAMES:
        return MODEL_ARCH_NAMES[a]
    if a.endswith("-assistant"):                  # a head shipped beside a family
        return "%s assistant (MTP drafter)" % arch_label(a[:-len("-assistant")])
    for pre, fam in (("qwen3", "Qwen 3 family"), ("qwen2", "Qwen 2 family"),
                     ("gemma", "Gemma family"), ("llama", "Llama family"),
                     ("deepseek", "DeepSeek family"), ("mistral", "Mistral family"),
                     ("phi", "Phi family"), ("rwkv", "RWKV family")):
        if a.startswith(pre):
            return fam + (" (MoE)" if "moe" in a else "")
    return a

# The names people who make these models actually use, checked against the header
# field that carries them. llama.cpp reports architecture "llama" for Mistral,
# NeMo and Yi alike - the family is all the tensors can say - so where the arch is
# a broad one, general.name is consulted for the narrower name. That is a header
# field, read like any other, not a guess from the filename. (p118)
ARCH_SUBFAMILY = {
    "llama": ("Mistral", "NeMo", "Yi", "Vicuna", "SOLAR", "Nous", "Airoboros",
              "Zephyr", "TinyLlama", "CodeLlama"),
    "qwen2": ("Yi",),
}


def arch_name_from_string(a):
    """spark2_5 -> Spark 2.5, muse-glimmer -> Muse-Glimmer, foo9000 -> Foo 9000:
    the architecture string, spaced and cased for a reader, nothing invented."""
    s = re.sub(r"[^a-z0-9._-]", "", str(a or "").strip().lower())
    if not s:
        return ""
    s = s.replace("_", ".")
    s = re.sub(r"(?<=[a-z])(?=[0-9])", " ", s)
    s = re.sub(r"(?<=[0-9])(?=[a-z])", " ", s)
    s = re.sub(r"(^|[\s-])([a-z])", lambda m: m.group(1) + m.group(2).upper(), s)
    return s.strip(" .-")


def arch_family(arch, name=""):
    """The FAMILY, and nothing else - no type, no MoE, no explanation.

    arch_label describes a FILE: it appends "assistant (MTP drafter)", "(MoE)",
    and for llama a note that the family also covers Mistral and NeMo. All true,
    and all wrong for a label whose whole job is to say which family this is -
    the type is stated separately and does not want saying twice. (p118)
    """
    a = str(arch or "").strip().lower()
    if not a:
        return ""
    # A head, a drafter and an MoE variant all belong to the family they are
    # built from: gemma4-assistant is Gemma 4, lfm2moe is LFM2, dflash-draft is
    # a drafter of whatever it drafts for. The owner's own cache showed lfm2moe
    # and dflash-draft coming out with NO family because only the -assistant
    # suffix was peeled. (p118, widened p119)
    for _suf in ("-assistant", "-draft", "-drafter"):
        if a.endswith(_suf):
            a = a[:-len(_suf)]
            break
    lab = MODEL_ARCH_NAMES.get(a, "")
    if not lab:
        # an moe suffix is a variant of a family, not a family of its own
        _base = re.sub(r"moe$", "", a)
        lab = MODEL_ARCH_NAMES.get(_base, "")
    if not lab:
        for pre, fam in (("qwen3", "Qwen 3"), ("qwen2", "Qwen 2"),
                         ("gemma", "Gemma"), ("llama", "Llama"),
                         ("deepseek", "DeepSeek"), ("mistral", "Mistral"),
                         ("phi", "Phi"), ("rwkv", "RWKV"), ("lfm", "LFM2"),
                         ("granite", "Granite"), ("olmo", "OLMo")):
            if a.startswith(pre):
                lab = fam
                break
    if not lab:
        # THE FILE SAID WHAT IT IS. spark2_5 was not in the table and not under
        # any prefix, so the row said nothing while the card showed the
        # architecture plainly. A name the panel has no pretty form for is
        # still a name: it is read from the architecture string itself -
        # spark2_5 -> Spark 2.5 - so no new family is ever blank again. (p181)
        lab = arch_name_from_string(a)
        if not lab:
            return ""
    # A projector's architecture IS its type - "vision projector (CLIP/ViT)"
    # is not a family, and the row already says vision after the name.
    # Nothing to add, so nothing is said. (p118)
    # ...and neither does a name that states a ROLE rather than a lineage.
    # dflash-draft resolved to "DFlash drafter", which is what the file does and
    # not what it came from - the row says draft after the name already. (p119)
    _l = lab.lower()
    if ("projector" in _l or "encoder" in _l or "drafter" in _l
            or "draft" in _l or "assistant" in _l):
        return ""
    lab = lab.split(" - ")[0]                       # drop the explanation
    lab = re.sub(r"\s*\((MoE|Meta)\)\s*$", "", lab)
    lab = re.sub(r"\s+family$", "", lab).strip()
    # the narrower name, when the header states one this family is known by
    low = str(name or "").lower()
    for sub in ARCH_SUBFAMILY.get(a, ()):
        if sub.lower() in low:
            return sub
    return lab


# A drafter that says what it is in its own header. Meta's Muse Glimmer ships its
# DFlash assistant as architecture "dflash" with ordinary tensor names, so the
# tensor scan - which finds Gemma's MTP and EAGLE heads by name - could never have
# found it. The header is the stronger fact anyway: it is what llama.cpp reads.
DRAFT_ARCHS = frozenset(("dflash", "mtp", "nextn", "eagle", "eagle2", "eagle3",
                         "medusa", "draft"))


def is_draft_arch(arch):
    """Does this architecture belong to a speculative drafter?

    Named kinds, plus the convention llama.cpp itself follows for a head shipped
    beside a family: Gemma 4's MTP head declares `gemma4-assistant`, and its
    tensors are named like any other model's, so nothing but the architecture
    can tell it apart from a small chat model."""
    a = str(arch or "").strip().lower()
    if not a:
        return False
    # ...and the SUFFIXED forms. The owner's cache had gemma4-31b-it-dflash
    # filed as arch "dflash-draft" with kind "main", so a DFlash drafter was
    # offered as a language model: the set holds "dflash" and the header said
    # "dflash-draft". A membership test on a name that carries suffixes has to
    # allow for them. (p119)
    if a in DRAFT_ARCHS or a.endswith("-assistant"):
        return True
    for _s in ("-draft", "-drafter"):
        if a.endswith(_s):
            return True                            # the name says so itself
    return False

# What a tensor is stored AS. ggml numbers its types and every GGUF names the
# type of every tensor it holds, so the quantisation of a file is a fact to be
# read off the tensors rather than a word in a filename - which is exactly what
# a rename or a repack destroys. (p50)
GGML_TYPE_NAMES = {0: "F32", 1: "F16", 2: "Q4_0", 3: "Q4_1", 6: "Q5_0",
                   7: "Q5_1", 8: "Q8_0", 9: "Q8_1", 10: "Q2_K", 11: "Q3_K",
                   12: "Q4_K", 13: "Q5_K", 14: "Q6_K", 15: "Q8_K",
                   16: "IQ2_XXS", 17: "IQ2_XS", 18: "IQ3_XXS", 19: "IQ1_S",
                   20: "IQ4_NL", 21: "IQ3_S", 22: "IQ2_S", 23: "IQ4_XS",
                   24: "I8", 25: "I16", 26: "I32", 27: "I64", 28: "F64",
                   29: "IQ1_M", 30: "BF16", 34: "TQ1_0", 35: "TQ2_0"}


def gguf_meta(path):
    """Read a few named values out of a GGUF header, without reading the weights.

    Returns {} for anything that is not a readable GGUF - a model is never rejected
    just because we could not inspect it. What a file is stored AS is a separate
    question, answered by gguf_tensor_scan in the one pass it already makes over
    the tensor table. (p50)
    """
    out = {}
    # DID THE HEADER END WHERE IT SAID IT WOULD. Windows gives a file being
    # copied its full length at once and fills it in behind; a read that
    # overtakes the copy gets zeros, which parse as empty keys with value 0
    # and raise nothing - so general.architecture, the first key, came back
    # true and everything after it came back missing, and the owner's
    # test.gguf was remembered as a complete "other" until a restart. A real
    # header has no empty key: one ends the read, and the record says so.
    # (p178)
    _cut = False
    _done = 0
    _started = False                # only a header that BEGAN can end early
    try:
        with open(path, "rb") as f:
            if f.read(4) != b"GGUF":
                return out
            _started = True
            f.read(4)                                   # format version
            f.read(8)                                   # tensor count
            n = int.from_bytes(f.read(8), "little")
            if n > 4096:                                # not a header we understand
                return out
            def rd_str():
                ln = int.from_bytes(f.read(8), "little")
                if ln > (1 << 20):
                    raise ValueError("string too long")
                return f.read(ln).decode("utf-8", "replace")
            SZ = {0: 1, 1: 1, 2: 2, 3: 2, 4: 4, 5: 4, 6: 4, 7: 1, 10: 8, 11: 8, 12: 8}
            for _ in range(n):
                k = rd_str()
                if not k:
                    _cut = True
                    break                               # zeros: the copy has not reached here
                ty = int.from_bytes(f.read(4), "little")
                if ty == 8:
                    v = rd_str()
                    # The chat template is the ONE place a thinking mode is
                    # written down in a form that can be read. Whether a model
                    # was TRAINED to reason cannot be read from a file at all -
                    # there is no tensor for it and no header field - but whether
                    # its template emits a reasoning block, and whether that is
                    # gated by a switch, is plainly there. Kept as two flags
                    # rather than the template itself, which can run to tens of
                    # kilobytes. (p116)
                    if k == "tokenizer.chat_template":
                        _lv = v.lower()
                        # A SWITCH is unambiguous: the name is only there to be
                        # set. WHERE the tag is written is the harder question -
                        # LFM2.5-1.2B-Instruct mentions <think> in a
                        # keep_past_thinking option that preserves blocks from
                        # earlier turns, and reads as "always thinks" to any
                        # plain substring search. What separates the two is the
                        # GENERATION PROMPT: a model primed to reason emits the
                        # tag while opening the assistant turn, so only a <think>
                        # after the last add_generation_prompt counts. (p116)
                        # Templates do not agree on ANY of this. The switch is
                        # enable_thinking on Qwen and plain thinking on others;
                        # the opener is <think>, or a harmony channel, or
                        # [THINK]; and reasoning_effort is a third thing again -
                        # a level rather than a switch, which is what llama.cpp
                        # drives with --reasoning-effort. Looking only for
                        # <think> and enable_thinking left every Muse Glimmer
                        # and five of six LFM2 files saying nothing at all.
                        # (p116, widened p126)
                        out["_tmplSwitch"] = any(
                            k in _lv for k in ("enable_thinking", "add_thinking",
                                               "{%- if thinking", "{% if thinking",
                                               "thinking is defined"))
                        out["_tmplEffort"] = "reasoning_effort" in _lv
                        _gp = _lv.rfind("add_generation_prompt")
                        out["_tmplThink"] = bool(
                            _gp >= 0 and any(k in _lv[_gp:] for k in
                                             ("<think>", "<reasoning>", "[think]",
                                              "<|channel|>analysis", "<seed:think>")))
                        v = ""            # not kept: only the two answers are
                elif ty == 7:
                    v = bool(f.read(1)[0])
                elif ty in _GGUF_FLOAT:
                    # 6 is FLOAT32 and 12 is FLOAT64. Reading them with
                    # int.from_bytes stores the BIT PATTERN: the owner's cache
                    # held ropeBase 1315859240, which is what 1000000000.0 looks
                    # like read as an integer. Nothing had used it yet, so it
                    # cost nothing - but a wrong number that is stable is exactly
                    # the kind that gets trusted later. (p122)
                    v = _struct.unpack(_GGUF_FLOAT[ty],
                                       f.read(SZ[ty]))[0]
                elif ty in SZ:
                    v = int.from_bytes(f.read(SZ[ty]), "little")
                elif ty == 9:
                    # short numeric arrays are READ - a hyperparameter stated per
                    # layer is still a hyperparameter (p126)
                    v = gguf_read_small_array(f, SZ)
                else:
                    _cut = True
                    break                               # unknown kind: stop, keep what we have
                # the named keys, plus a drafter's own block size and any model's
                # block count - one says how deep it drafts, the other says the
                # file is a language model and not a projector (patch185)
                if k in GGUF_WANT or k.endswith((".block_size", ".block_count",
                                                 ".context_length",
                                                 ".attention.sliding_window",
                                                 # each of these decides a
                                                 # llama.cpp flag: the expert
                                                 # counts feed --n-cpu-moe, the
                                                 # rope scaling feeds
                                                 # --rope-scaling and the yarn
                                                 # dials, the window pattern says
                                                 # how often a full-attention
                                                 # layer breaks the window, and
                                                 # the kv head count is the GQA
                                                 # ratio that sizes the cache.
                                                 # Key names taken from
                                                 # llama.cpp's own constants.py,
                                                 # not guessed. (p116)
                                                 ".expert_count",
                                                 ".expert_used_count",
                                                 ".rope.scaling.type",
                                                 ".attention.sliding_window_pattern",
                                                 ".attention.head_count",
                                                 ".attention.head_count_kv",
                                                 # A drafter must agree with its
                                                 # parent on ALL of these, not
                                                 # just the embedding width: the
                                                 # owner's own folder had a
                                                 # DFlash drafter and a Gemma 4
                                                 # sharing width 5376, so one
                                                 # number pairs the wrong two
                                                 # models. Names from llama.cpp's
                                                 # constants.py. (p120)
                                                 ".feed_forward_length",
                                                 ".vocab_size",
                                                 ".attention.key_length",
                                                 ".attention.value_length",
                                                 ".rope.freq_base",
                                                 ".embedding_length",
                                                 ".embedding_length_out",
                                                 ".projection_dim",
                                                 ".sample_from_anchor",
                                                 # EVERY audio.cpp GGUF writes
                                                 # general.architecture as
                                                 # "audiocpp" - the family it
                                                 # really is lives here, and is
                                                 # the only reliable signal (p56)
                                                 ".model_spec.family")):
                    out[k] = v
                _done += 1
    except Exception:
        _cut = True
    if _started:                    # a file that would not open is {} as it always was
        out["_hdrDone"] = (not _cut) and _done == n
    return out

def _is_quantised(name):
    """Is this ggml type a quantisation, or a plain float or integer? (p62)"""
    n = str(name or "").upper()
    return n.startswith("Q") or n.startswith("IQ") or n.startswith("TQ")


def gguf_tensor_scan(path, block_count=0):
    """Read EVERY tensor name in a GGUF and report the markers that decide what
    the file is and what it can do. Names only, never weights.

    Reading all of them matters: the tensor that says a model drafts for itself
    sits at the END of the list - blk.{block_count-1}.nextn.* - and a scan capped
    at the first few hundred names walked straight past it on any model above a
    few dozen layers. llama.cpp types an MTP drafter by exactly that tensor
    (common_speculative_types_from_gguf), so the panel reads the same fact the
    same way. Returns None for anything that is not a readable GGUF. (patch2)
    """
    out = {"vision": False, "blk0": False, "nextn_last": False,
           "mtp_names": False, "eagle_names": False, "markov": False,
           "moe_names": False, "convLayers": 0, "attnLayers": 0,
           # where the tensor data must reach, taken from the table itself:
           # the file cannot be complete while it is shorter than this (p173)
           "lastOffset": 0, "dataStart": 0}
    try:
        with open(path, "rb") as f:
            if f.read(4) != b"GGUF":
                return None
            f.read(4)
            ntensor = int.from_bytes(f.read(8), "little")
            nkv = int.from_bytes(f.read(8), "little")
            if ntensor > 100000 or nkv > 4096:
                return None
            def rd_str():
                ln = int.from_bytes(f.read(8), "little")
                if ln > (1 << 20):
                    raise ValueError("string too long")
                return f.read(ln).decode("utf-8", "replace")
            SZ = {0: 1, 1: 1, 2: 2, 3: 2, 4: 4, 5: 4, 6: 4, 7: 1, 10: 8, 11: 8, 12: 8}
            for _ in range(nkv):                      # step over the header values
                rd_str()
                ty = int.from_bytes(f.read(4), "little")
                if ty == 8:
                    ln = int.from_bytes(f.read(8), "little")
                    f.seek(ln, 1)
                elif ty in SZ:
                    f.seek(SZ[ty], 1)
                elif ty == 9:
                    gguf_skip_array(f, SZ)
                else:
                    return None
            last = "blk.%d.nextn.eh_proj.weight" % (int(block_count or 0) - 1)
            _qc = {}                                  # ggml type -> elements held
            _conv_blk, _attn_blk = set(), set()        # which blocks are which
            for _ in range(ntensor):                  # then ALL the tensor names
                name = rd_str().lower()
                if name.startswith("v.") or name.startswith("mm.") or "vision_model" in name \
                        or name.startswith("resampler.") or name.startswith("mmproj"):
                    out["vision"] = True
                elif name.startswith("blk.0."):
                    out["blk0"] = True
                elif name == last:
                    out["nextn_last"] = True
                elif name == "markov_w1.weight":
                    out["markov"] = True
                if "mtp" in name or "nextn" in name:
                    out["mtp_names"] = True
                if "eagle" in name:
                    out["eagle_names"] = True
                # WHICH layers attend. A hybrid names its convolution layers
                # blk.N.shortconv.* and its attention layers blk.N.attn_*, so
                # counting the block numbers on each side says how the model is
                # actually built - and that is the fact behind an LFM2's small
                # KV cache: only the attending layers hold one. Counted from the
                # names llama.cpp itself writes, not from an architecture tag.
                # (p115)
                if ".shortconv." in name or ".operator_norm" in name:
                    _b = name.split(".")
                    if len(_b) > 1 and _b[0] == "blk" and _b[1].isdigit():
                        _conv_blk.add(int(_b[1]))
                elif ".attn_q." in name or ".attn_k." in name:
                    _b = name.split(".")
                    if len(_b) > 1 and _b[0] == "blk" and _b[1].isdigit():
                        _attn_blk.add(int(_b[1]))
                if "ffn_gate_exps" in name or "ffn_down_exps" in name:
                    out["moe_names"] = True
                nd = int.from_bytes(f.read(4), "little")
                if nd > 8:
                    return None
                # the same pass answers what the file is stored AS. Types are
                # weighed by element count, so the handful of full-precision
                # norms every quantised model keeps cannot outvote the weights,
                # and no second walk of the same table is needed. (p50)
                elems = 1
                for _d in range(nd):
                    elems *= max(1, int.from_bytes(f.read(8), "little"))
                ty = int.from_bytes(f.read(4), "little")
                _off = int.from_bytes(f.read(8), "little")
                if _off > out["lastOffset"]:
                    out["lastOffset"] = _off
                _qc[ty] = _qc.get(ty, 0) + elems
            if _qc:
                # What a file IS quantised to is decided by its QUANTISED
                # tensors. Every quantised model keeps norms, and often its
                # embeddings, at full precision - in a small model those can
                # outweigh the weights by element count, which is how two
                # q8_0 files in the field reported F32. Floats only answer when
                # nothing is quantised at all. (p62)
                _qq = dict((_ty, _n) for _ty, _n in _qc.items()
                           if _is_quantised(GGML_TYPE_NAMES.get(_ty, "")))
                _pool = _qq or _qc
                _top = max(_pool, key=lambda k: _pool[k])
                out["quant"] = GGML_TYPE_NAMES.get(_top, "type %d" % _top)
                # and the whole mix travels with it, so the verdict can be
                # checked rather than believed
                out["quant_mix"] = dict(
                    (GGML_TYPE_NAMES.get(_ty, "type %d" % _ty), _n)
                    for _ty, _n in sorted(_qc.items(), key=lambda kv: -kv[1]))
            out["convLayers"] = len(_conv_blk)
            out["attnLayers"] = len(_attn_blk)
            # the weights begin after the table, aligned up to the file's own
            # alignment (32 unless the header says otherwise)
            # 32 is GGUF's default alignment; a file declaring more would
            # only push this higher, so taking the default keeps the bound safe
            _here = f.tell()
            out["dataStart"] = ((_here + 31) // 32) * 32
    except Exception:
        return None
    return out

_KIND_FILE = os.path.join(STACK, "model-kinds.json")
# audio.cpp models are a different subject with different questions - which
# family, which quantisation, why the TTS pages read it that way - and mixing
# them into the language-model book made both harder to read. Same format, same
# rules, same reader; a separate book. (p58)
_TTS_KIND_FILE = os.path.join(STACK, "tts-model-kinds.json")
_KIND = {"map": None, "dirty": False, "file": _KIND_FILE}
_TKIND = {"map": None, "dirty": False, "file": _TTS_KIND_FILE}
_KIND_LOCK = threading.Lock()
# WHAT THE LOAD WANTS TO SAY, said once it is safe to say it. _kind_map runs
# inside _KIND_LOCK, and panel_log reaches log_dir -> load_config, which is disk
# work that on a first load can come back round to a model read - and the lock is
# a plain threading.Lock, so that is a deadlock, not a slow path. patch122 put a
# log line in there and the panel stopped reporting a port at all. A load path
# does not log; it leaves a note. (p123)
_KIND_SAY = []


# ------------------------------------------------------------------ readiness
# WHAT IS AND IS NOT READY YET, said once, in one place.
#
# Until now nothing knew this. Every part of the page that drew before its data
# arrived had to invent an explanation for the emptiness, and picked a wrong one:
# the model menu said "not in models folder" about files that were sitting right
# there, because the only two answers it had were "here" and "absent" and the
# truth was "not looked yet". A panel that cannot say it is still working will
# always describe working as failure.
#
# Each step declares itself before it starts, so a step that never runs is still
# visible as waiting rather than simply missing. (p128)
READY_STEPS = (
    ("config",   "Settings and folders"),
    ("install",  "Checking this install"),
    ("gpus",     "Finding graphics cards"),
    ("models",   "Reading the models folder"),
    ("tts",      "TTS voice packs"),
    ("proxy",    "SkyrimNet proxy"),
    ("servers",  "Server status"),
)
_READY = {}
_READY_LOCK = threading.Lock()


def ready_init():
    """Declare every step as waiting, before any of them starts."""
    with _READY_LOCK:
        _READY.clear()
        for key, label in READY_STEPS:
            _READY[key] = {"label": label, "state": "waiting", "note": "",
                           "at": time.time(), "took": 0.0}


def ready_mark(key, state, note=""):
    """Move one step on. Unknown keys are recorded rather than dropped, because a
    step nobody declared is worth seeing, not hiding."""
    now = time.time()
    with _READY_LOCK:
        cur = _READY.get(key) or {"label": key, "state": "waiting",
                                  "at": now, "took": 0.0}
        if state == "working":
            cur["at"] = now
        elif cur.get("at"):
            cur["took"] = max(0.0, now - cur["at"])
        cur["state"] = state
        if state in ("ready", "failed"):
            # written where it can be read after the screen has gone: the owner
            # asked what is checked, for how long, and why - a line per step
            # answers all three (p130)
            try:
                panel_log("[start] %-26s %-7s %5.1fs %s"
                          % (cur.get("label") or key, state, cur.get("took") or 0.0,
                             note or cur.get("note") or ""))
            except Exception:
                pass
        # A NOTE SURVIVES THE STEP FINISHING. "139 found" is set while the step
        # is working and is the whole point of the line; clearing it on the way
        # out - which an empty default did - threw away the only fact worth
        # reading. Only an explicit new note replaces one. (p128)
        if note:
            cur["note"] = str(note)[:160]
        _READY[key] = cur


def ready_step(key, note=""):
    """A step, marked working on the way in and ready or failed on the way out.

    Wrapping it means a step that throws is reported as failed rather than left
    saying "working" for ever - which is exactly how a progress display comes to
    lie about what it is doing.
    """
    class _Step(object):
        def __enter__(self_):
            ready_mark(key, "working", note)
            return self_

        def __exit__(self_, et, ev, tb):
            if et is None:
                ready_mark(key, "ready")
            else:
                ready_mark(key, "failed", str(ev)[:160])
                # and it is an ERROR: the launch view shows it once and is gone,
                # panel.log keeps the line, but the issue record on the Log page
                # - the place a reader looks for what went wrong - knew nothing
                # of it (p141)
                try:
                    log_error("start", "%s failed: %s"
                              % ((_READY.get(key) or {}).get("label") or key, str(ev)[:200]))
                except Exception:
                    pass                    # recording the failure must not raise inside __exit__
            return False
    return _Step()


def ready_state():
    """The whole picture, for the page. `done` is the one question that matters."""
    with _READY_LOCK:
        steps = [dict(_READY[k], key=k) for k, _ in READY_STEPS if k in _READY]
    done = all(s["state"] in ("ready", "failed") for s in steps) if steps else False
    return {"steps": steps, "done": done,
            "ready": len([s for s in steps if s["state"] == "ready"]),
            "total": len(steps)}


def _kind_say_flush():
    """Say anything the cache load wanted to say. Called with NO lock held."""
    while _KIND_SAY:
        try:
            panel_log(_KIND_SAY.pop(0))
        except Exception:
            pass
# patch122 fixed float decoding, so ropeBase changed from a bit pattern to a
# number. The per-field drop below could not catch it: the field was PRESENT,
# merely wrong, and that rule only re-reads an entry that is MISSING one. A value
# whose meaning changed is what this stamp is for - it is written on the line
# that defines it, and patch122 used the other mechanism anyway. 120 of the
# owner's 139 entries went on holding 1315859240 for 1000000000.0. (p125)
_KIND_RULES = "376p149"      # bumped whenever what a remembered verdict MEANS changes
# A KEY THAT CANNOT BE THIS MACHINE'S IS NOT THIS MACHINE'S. For thirty-odd
# patches every gate run wrote its temporary models into the TTS ledger that
# then SHIPPED, so an install carries hundreds of /tmp/gate-... records that
# no scan will ever walk and the p172 pruner therefore never drops. A POSIX
# temp path is not a file on a Windows machine; such a key is dropped when
# the ledger is read and the file rewritten without it. Empty everywhere
# else, so a developer's own /tmp models are left alone. (p177)
_FOREIGN_KEY = ("/tmp/",) if os.name == "nt" else ()
# Every fact a remembered verdict carries. A stamp bump covers a verdict whose
# MEANING changed; this covers one that has gained a new fact, which is not the
# same thing and was twice missed - hotfix2 added `embd`, patch3 added `embdOut`,
# neither bumped the stamp, and 118 of one owner's 128 entries went on answering
# "how wide is this?" with silence. Silence is indistinguishable from a pass, so
# the bad-match warning could not fire on any file he had not re-quantised since.
# Named here so an entry that cannot answer is dropped rather than trusted, and
# so a field added without a thought spent on the cache re-reads instead of going
# quiet. (v3.76 patch12)
# EVERY FACT A VERDICT IS MADE OF. The gate holds this equal to the keys
# _model_facts_read returns (p12), so a field added to one without the other
# fails the build rather than going quiet - which is why p151 did NOT replace
# this with a runtime derivation off the reader's source: the drift it would
# have guarded against is already impossible, and parsing our own source at
# import time to prove it would be the more fragile of the two. (p151)
_KIND_FIELDS = ("arch", "blocks", "ctx", "embd", "embdOut", "kind", "label",
                "mtpHead", "size", "spec", "swa", "spec_family", "tts_why",
                "quant", "tts_fam", "tts_role", "quant_mix",
                # how the layers divide: a hybrid holds a KV cache only for the
                # ones that attend, which is why its cache is small (p115)
                "convLayers", "attnLayers", "moe", "family",
                "swaEvery", "experts", "expertsUsed", "rope", "heads", "headsKv",
                "ffn", "vocab", "keyLen", "valLen", "ropeBase",
                "reasonTmpl")


def _kind_store(val):
    """Which book a record belongs in - decided by what the file turned out to
    be, because nothing before the read can tell. (p58)"""
    return (_TKIND if ((val or {}).get("spec_family")
                       or (val or {}).get("arch") == "audiocpp") else _KIND)


def _kind_map(store=None):
    _KIND_ = store or _KIND
    if _KIND_["map"] is None:
        try:
            with open(_KIND_["file"], encoding="utf-8") as f:
                _m = json.load(f) or {}
            _alien = [_k for _k in _m
                      if _k != "_rules" and str(_k).startswith(_FOREIGN_KEY)]
            if _alien:                          # never this machine's (p177)
                for _k in _alien:
                    _m.pop(_k, None)
                _KIND_["dirty"] = True
                _KIND_SAY.append(
                    "[models] %d remembered %s never this machine's (left by "
                    "the developer's test runs) - dropped"
                    % (len(_alien), "entry was" if len(_alien) == 1 else "entries were"))
            # every verdict in the file was reached under the rules of its day; when
            # those rules change, the file is stale even though the models are not.
            # Muse Glimmer's drafter was cached as a plain model (patch185); the
            # qwen35 heads were cached before the tensor rule and the built-in-head
            # fact existed (patch2).
            _m = _m if _m.get("_rules") == _KIND_RULES else {"_rules": _KIND_RULES}
            # and an entry that predates a fact cannot answer for it. Dropped one
            # by one rather than the whole file, so the entries that DO carry
            # every field are kept and only what must be re-read is re-read.
            _KIND_["map"] = dict((_k, _v) for _k, _v in _m.items()
                                 if _k == "_rules"
                                 or (isinstance(_v, dict)
                                     and all(_f in _v for _f in _KIND_FIELDS)))
            # SAY SO. The owner watched this file's timestamp for two patches and
            # could not tell whether it was working or stuck - a record that is
            # correctly unchanged looks exactly like one that is broken. Now the
            # panel log says which: how many entries were kept, how many dropped,
            # and for which missing fact. A patch that only changes how something
            # is DRAWN touches nothing here, and that is worth reading too. (p122)
            _was = len([_k for _k in _m if _k != "_rules"])
            _now = len([_k for _k in _KIND_["map"] if _k != "_rules"])
            if _was != _now:
                _miss = set()
                for _k, _v in _m.items():
                    if _k == "_rules" or not isinstance(_v, dict):
                        continue
                    for _f in _KIND_FIELDS:
                        if _f not in _v:
                            _miss.add(_f)
                _KIND_SAY.append(
                    "[models] %d of %d remembered models must be re-read: "
                    "they predate %s"
                    % (_was - _now, _was, ", ".join(sorted(_miss)) or "?"))
            elif _was:
                _KIND_SAY.append(
                    "[models] %d remembered models are up to date - "
                    "nothing to re-read" % _was)
        except Exception:
            _KIND_["map"] = {"_rules": _KIND_RULES}
    return _KIND_["map"]
def _kind_forget_missing(roots):
    """Drop the record of any file under these folders that is no longer there.
    Only these folders: a path the scan did not walk says nothing about whether
    its file exists. (p172)"""
    try:
        heads = tuple(os.path.abspath(r).lower().rstrip("\\/") + os.sep
                      for r in (roots or []) if r)
    except Exception:
        return 0
    if not heads:
        return 0
    gone = 0
    for _bk in (_KIND, _TKIND):
        with _KIND_LOCK:
            m = _kind_map(_bk)
            dead = [k for k in m
                    if k.startswith(heads) and not os.path.exists(k)]
            for k in dead:
                m.pop(k, None)
                _bk["dirty"] = True
            gone += len(dead)
    return gone                 # the caller says it, OUTSIDE the lock (p172)
def _kind_flush():
    for _store in (_KIND, _TKIND):
        _kind_flush_one(_store)


def _kind_flush_one(_KIND_):
    with _KIND_LOCK:
        if not _KIND_["dirty"]:
            return
        data = dict(_KIND_["map"] or {})
        _KIND_["dirty"] = False
    try:
        tmp = _KIND_["file"] + ".%d.tmp" % os.getpid()
        with open(tmp, "w", encoding="utf-8") as f:
            # one record per line: this file is read by people when a model is
            # not recognised, and a single 40,000-character line is not (p57)
            json.dump(data, f, indent=1, sort_keys=True)
        os.replace(tmp, _KIND_["file"])
    except Exception:
        pass
def model_kind(path):
    """Cached in front of the header read: identifying a .gguf means opening it, and
    a models folder full of multi-gigabyte files turned that into tens of seconds on
    every scan. The key is path + size + mtime, so a changed file is re-read."""
    try:
        stt = os.stat(path)
        key = _kind_key(path)
    except Exception:
        return _model_kind_read(path)
    # one lookup, in one place: this used to be a second copy of the block in
    # model_facts, and a second copy is a second thing to keep right (p58)
    return str((model_facts(path) or {}).get("kind") or "")

def _spec_kind(arch, scan):
    """Which KIND of speculation this file would perform as a drafter.

    llama.cpp names one implementation per kind and runs none unless told which.
    Its own inference (common_speculative_types_from_gguf) reads the TENSORS,
    not the architecture: a non-DFlash file is an MTP drafter iff it carries
    blk.{block_count-1}.nextn.eh_proj.weight - the qwen35-generation heads
    declare the FAMILY architecture, so an architecture-only rule read them as
    plain drafters and llama-server tried to load a one-layer head file as a
    65-layer model. Where llama.cpp infers nothing (assistant heads, EAGLE,
    plain small models), the kind the file demands is still stated. (patch2)
    """
    a = str(arch or "").strip().lower()
    sc = scan or {}
    if a == "dflash":
        # the Markov head is what tells a DSpark drafter from a DFlash one
        return "draft-dspark" if sc.get("markov") else "draft-dflash"
    if a.startswith("eagle"):
        return "draft-eagle3"
    if a.endswith("-assistant") or "mtp" in a or "nextn" in a \
            or sc.get("nextn_last") or sc.get("mtp_names"):
        return "draft-mtp"
    if sc.get("eagle_names"):
        return "draft-eagle3"
    return "draft-simple"           # a whole small model of the same family


def _tts_why_read(meta, arch):
    """One line saying what a file told the TTS pages about itself. (p57)"""
    spec = str(meta.get("audiocpp.model_spec.family")
               or meta.get(arch + ".model_spec.family") or "").strip()
    if spec:
        return "declares audio.cpp family %s" % spec
    if arch and arch != "audiocpp":
        return "no audio.cpp family key; architecture %s" % arch
    if arch == "audiocpp":
        return ("architecture audiocpp with no family key - an audio.cpp file "
                "the converter did not stamp, or a key this reader missed")
    return "no architecture and no family key - header unreadable or not a GGUF"


def _tts_fam_read(meta, arch):
    """The panel's own verdict on a file, from its header alone. (p60)"""
    return tts_model_family("", {"spec_family": str(
        meta.get("audiocpp.model_spec.family")
        or meta.get(arch + ".model_spec.family") or "").lower(), "arch": arch})


def _tts_role_read(meta, arch):
    """What that verdict MEANS to the TTS pages, in words. (p60, corrected p61)

    Since p61 a bare architecture is an answer too, so the wording has to say
    WHICH answer it was: an audio.cpp package that names a family we carry no
    pack for is a different thing from a file that is not an audio.cpp package
    at all, and calling an LTX quant "another audio.cpp family" was simply wrong.
    """
    fam = _tts_fam_read(meta, arch)
    spec = str(meta.get("audiocpp.model_spec.family")
               or meta.get(arch + ".model_spec.family") or "").strip()
    if fam in TTS_PACKS:
        return "tts pack: %s" % TTS_PACKS[fam]["label"]
    if fam == "asr":
        return "recogniser"
    if spec:
        return "another audio.cpp family - the panel carries no pack for it"
    if fam:
        return ("not an audio.cpp package - it declares architecture %s, so it "
                "is not one of the panel's TTS models" % fam)
    return "not identified"


def _model_facts_read(path):
    """Everything the card needs about a .gguf, from ONE header read: what it is,
    which family it belongs to, the two numbers worth showing beside that, the
    kind of speculation it would perform as a drafter, and whether - as a model -
    it carries its own MTP head and drafts for itself."""
    _MODEL_READ_WHY.pop(os.path.abspath(path).lower(), None)
    try:
        return _model_facts_read_raw(path)
    except Exception as e:
        # WHY, in the reader's own words, so the fifth-attempt error names a
        # cause instead of saying only that something failed (p151)
        _MODEL_READ_WHY[os.path.abspath(path).lower()] = "%s: %s" % (type(e).__name__, e)
        raise


def _model_facts_read_raw(path):
    """The read itself."""
    meta = gguf_meta(path)
    if meta and not meta.get("_hdrDone"):
        # partial is not a reading; the ledger must see this as a read that
        # did not finish, or it remembers half a header for ever (p178)
        raise ValueError("the header ends early - the file is still being "
                         "copied in, or was cut short")
    arch = str(meta.get("general.architecture") or "").lower()
    # THIS ONE SITS OUTSIDE THE DICT, and a sweep that read only the dict never
    # saw it. It is the line the owner's panel actually died on - int() of a
    # per-layer list - and it is why no model in his folder could be read at all.
    # Wrapping "the ones I noticed" is what left it: the rule is that EVERY
    # header value goes through gguf_one_number, wherever it is read. (p129)
    blocks = int(gguf_one_number(meta.get(arch + ".block_count")))
    scan = gguf_tensor_scan(path, blocks)
    # THE FILE SAYS HOW BIG IT HAS TO BE. A model half-copied in reads as a
    # model: the header and the tensor table live at the FRONT, so they land
    # first and parse cleanly while the weights are still on their way. No timer
    # can answer that honestly - waiting longer is a guess about someone else's
    # disk. The table says where the data starts and how far into it the last
    # tensor sits, so a file shorter than that is not all here. It is read when
    # it is, because a changed size makes the record stale. (p173, at the
    # owner's word: deterministic, not a band-aid)
    if scan:
        _need = int(scan.get("dataStart") or 0) + int(scan.get("lastOffset") or 0)
        try:
            _have = os.path.getsize(path)
        except Exception:
            _have = 0
        if _need and _have + 32 < _need:
            raise RuntimeError("%d bytes short of what its own header declares "
                               "- still being copied in?" % (_need - _have))
    kind = _model_kind_read(path, meta, scan)
    return {"kind": kind, "arch": arch,
            # what an audio.cpp package says it is, in its own words. Absent from
            # a llama.cpp model, present in every audio.cpp one. (p56)
            "spec_family": str(meta.get("audiocpp.model_spec.family")
                               or meta.get(arch + ".model_spec.family") or "").lower(),
            # and WHY the TTS pages read it the way they do, in the same file a
            # user can open and send back. A model painted plain should be able
            # to say what it declared, or that it declared nothing at all. (p57)
            "tts_why": _tts_why_read(meta, arch),
            # and what the panel CONCLUDED from that - the file records the
            # question and the answer, so a wrong verdict can be read straight
            # out of it rather than reasoned about from the inputs (p60)
            "tts_fam": _tts_fam_read(meta, arch),
            "tts_role": _tts_role_read(meta, arch),
            # already read by the tensor walk above, and the first thing anyone
            # asks of a TTS model after which one it is (p58)
            "quant": str((scan or {}).get("quant") or ""),
            # every ggml type in the file and how many elements it holds, so a
            # quant verdict can be checked instead of believed (p62)
            "quant_mix": (scan or {}).get("quant_mix") or {},
            "label": arch_label(arch),
            # the family ALONE, derived here because general.name lives in the
            # header and is not kept - the type is stated separately on a row and
            # does not want saying twice (p118)
            "family": arch_family(arch, str(meta.get("general.name") or "")),
            "blocks": blocks,
            "ctx": int(gguf_one_number(meta.get(arch + ".context_length"))),
            # A windowed model declares its window in its own header. There are no
            # SWA tensors to find - unlike an MTP head, this is a hyperparameter,
            # so it is read here rather than looked for in the tensor list. (p51)
            "swa": int(gguf_one_number(meta.get(arch + ".attention.sliding_window"))),
            # what the TEMPLATE says about reasoning: "switch" when it can be
            # turned off through chat-template-kwargs, "always" when the template
            # writes a reasoning block with no switch to stop it, "" when it says
            # nothing. Read, never assumed. (p116)
            # switch beats effort beats always: a template that can be turned
            # off is the most useful thing to say, then one whose level can be
            # set, then one that simply reasons (p126)
            "reasonTmpl": ("switch" if meta.get("_tmplSwitch")
                           else "effort" if meta.get("_tmplEffort")
                           else "always" if meta.get("_tmplThink") else ""),
            # ...and the rest of what the header states about how this model
            # must be RUN. Every one of these is a fact llama.cpp itself acts
            # on, which is the test for whether it belongs on a card. (p116)
            "swaEvery": int(gguf_one_number(meta.get(arch + ".attention.sliding_window_pattern"))),
            "experts": int(gguf_one_number(meta.get(arch + ".expert_count"))),
            "expertsUsed": int(gguf_one_number(meta.get(arch + ".expert_used_count"))),
            "rope": str(meta.get(arch + ".rope.scaling.type") or ""),
            "heads": int(gguf_one_number(meta.get(arch + ".attention.head_count"))),
            "ffn": int(gguf_one_number(meta.get(arch + ".feed_forward_length"))),
            "vocab": int(gguf_one_number(meta.get(arch + ".vocab_size"))),
            "keyLen": int(gguf_one_number(meta.get(arch + ".attention.key_length"))),
            "valLen": int(gguf_one_number(meta.get(arch + ".attention.value_length"))),
            "ropeBase": int(float(gguf_one_number(
                meta.get(arch + ".rope.freq_base")) or 0)),
            "headsKv": int(gguf_one_number(meta.get(arch + ".attention.head_count_kv"))),
            "size": str(meta.get("general.size_label") or ""),
            "spec": _spec_kind(arch, scan),
            # The width this file speaks at, and - for a head that attaches to
            # another model - the width it hands BACK. A drafter whose `out` does
            # not equal its host's `embedding_length` cannot form the matmul, which
            # is the assert the owner's Gemma 4 launches died on. Same vocabulary,
            # so llama.cpp waves it through and finds out at graph build. (h2)
            "embd": int(gguf_one_number(meta.get(arch + ".embedding_length"))),
            # what this file hands BACK to a host, when it is something that attaches.
            # A projector is a clip file and says so under its own prefix; its
            # `clip.vision.embedding_length` is the vision tower's internal width and
            # is NOT the number llama.cpp compares. (v3.76 patch3)
            "embdOut": int(gguf_one_number(
                meta.get(arch + ".embedding_length_out")
                or meta.get("clip.vision.projection_dim")) or 0),
            "mtpHead": bool(kind == "main" and (scan or {}).get("nextn_last")),
            "convLayers": int((scan or {}).get("convLayers") or 0),
            "attnLayers": int((scan or {}).get("attnLayers") or 0),
            "moe": bool((scan or {}).get("moe_names"))}


def model_fit(main, other):
    """Whether `other` can attach to `main`. Returns "" when it can, or why not.

    ONE comparison, and it is the one the engine makes: the width a head hands back
    against the width its host expects. `embedding_length_out` is the head's answer;
    where a file does not declare one it speaks at its own `embedding_length`, which
    is the right fallback for a plain small drafter of the same family.

    Silence where the header does not say. A file with no width recorded is NOT
    reported as a bad match - an unknown is not a fault, and a warning painted over
    every unfamiliar file teaches people to ignore the colour. (v3.76 hotfix2)
    """
    try:
        want = int((main or {}).get("embd") or 0)
        # Does this file ATTACH? That is the question, not which field it happened to
        # fill in. A projector always attaches. A drafter attaches when it is an MTP,
        # assistant, EAGLE or DFlash head - all of which run against the host's hidden
        # state - and does not when it is a plain draft-simple model, which needs a
        # compatible vocabulary and any width at all.
        #
        # Asking "does embedding_length_out exist" instead was patch3's mistake: that
        # field is only on a STANDALONE head, so a whole model carrying nextn tensors
        # reported 0, and 0 meant silence. A 31B MTP drafter sat green beside a 26B
        # model and the warning vanished. (v3.76 patch10)
        _kind = str((other or {}).get("kind") or "")
        _spec = str((other or {}).get("spec") or "")
        attaches = (_kind == "vision"
                    or _spec in ("draft-mtp", "draft-eagle3",
                                 "draft-dflash", "draft-dspark"))
        if not attaches:
            return ""
        got = int((other or {}).get("embdOut") or 0) or int((other or {}).get("embd") or 0)
    except Exception:
        return ""
    if not want or not got or want == got:
        return ""
    return ("this attaches to a %d-wide model; %s is %d-wide"
            % (got, str((main or {}).get("label") or "the chosen model"), want))


def model_path_for_port(port):
    """The model file the server on `port` was launched with, from its slot."""
    try:
        for s in load_config_cached().get("slots", []):
            up = (parse_ps1_port(s.get("script") or "") if s.get("script") else None) or s.get("port")
            if str(up) == str(port):
                return (parse_ps1_model(s["script"]) if s.get("script") else "") or ""
    except Exception:
        pass                                # an unreadable slot is no model, not an error
    return ""


def model_note_trained(path, port):
    """THINKING: TRAINED, written on the file when three facts coincide: the
    server reported its thinking switch as supported, the request carried
    enable_thinking:false, and reasoning came back anyway. Not inferred from
    length or timing - a model that reasons with no markers is invisible to
    this and is not labelled. Saved with the file's other facts, under its
    identity, so it is forgotten if the file changes. (p143)"""
    if not path:
        return False
    try:
        props = slot_props(port) or {}
        # p143 refused this unless the server reported its switch supported; the
        # owner's LFM finetune has no switch in its template, was told no three
        # ways, and reasoned anyway - inside content, where llama.cpp's parser
        # leaves it when thinking is off. Two facts are the finding: the switch
        # was sent, reasoning came back. Whether the template HAD a switch is
        # kept as a detail beside the date. (p149)
        switched = bool(props.get("thinks"))
        stt = os.stat(path)
        key = _kind_key(path)
        with _KIND_LOCK:
            m = _kind_map(_KIND)
            hit = m.get(key)
            if not isinstance(hit, dict) or hit.get("reasonObserved") == "trained":
                return False
            hit["reasonObserved"] = "trained"
            hit["reasonObservedAt"] = time.strftime("%Y-%m-%d %H:%M")
            hit["reasonSwitch"] = "yes" if switched else "no"
            _KIND["dirty"] = True
        _kind_flush()
        _models_cache["t"] = 0             # the cards read the list; it must re-read the file
        panel_log("[reason] %s reasoned with thinking off on :%s - marked trained"
                  % (os.path.basename(path), port))
        return True
    except Exception:
        return False


# ONE ENTRY PER FILE. The key was path + size + mtime, so every size and mtime a
# file ever had left a record behind - a copy in progress passes through
# several, and a delete-and-repaste leaves the old one for ever. The FILE is the
# identity now, and what it looked like when it was read is kept inside the
# record: if the size or mtime has moved since, the record is stale and the file
# is read again. (p172, at the owner's word)
def _kind_key(path):
    return os.path.abspath(path).lower()
def _kind_stale(hit, stt):
    """Has the file moved under a record we already have?"""
    if not isinstance(hit, dict):
        return True
    return (int(hit.get("_size", -1)) != int(stt.st_size)
            or int(hit.get("_mtime", -1)) != int(stt.st_mtime))
MODEL_SCAN_TRIES = 5            # after this many failures on ONE file, stop and say why


def file_in_use(path):
    """Does another program hold this file open? True/False on Windows, where
    the copy that is still writing a file holds a handle on it and an
    exclusive open is refused with ERROR_SHARING_VIOLATION - the one signal
    that says "still arriving" rather than "broken". None where it cannot be
    asked. Asked only about a file that would not read, so a model a server
    holds open never comes here. (p178)"""
    if os.name != "nt":
        return None
    try:
        import ctypes
        _k32 = ctypes.WinDLL("kernel32", use_last_error=True)
        _k32.CreateFileW.restype = ctypes.c_void_p
        _k32.CreateFileW.argtypes = [ctypes.c_wchar_p, ctypes.c_uint32, ctypes.c_uint32,
                                     ctypes.c_void_p, ctypes.c_uint32, ctypes.c_uint32,
                                     ctypes.c_void_p]
        _k32.CloseHandle.argtypes = [ctypes.c_void_p]
        _h = _k32.CreateFileW(path, 0x80000000, 0, None, 3, 0x80, None)   # read, NO sharing
        if _h is None or _h == ctypes.c_void_p(-1).value:
            return ctypes.get_last_error() == 32                            # ERROR_SHARING_VIOLATION
        _k32.CloseHandle(_h)
        return False
    except Exception:
        return None
# why the last read of a file ended the way it did, in the reader's own words,
# so the fifth-attempt error names a cause instead of saying only that
# something failed. Set by the reader, read by the ledger. (p151)
_MODEL_READ_WHY = {}


def _facts_complete(f):
    """Every field the reader writes. A kind that legitimately has none of a
    thing still WRITES the field - the reader returns all 33 for every kind -
    so a missing one means the read did not finish, not that the model lacks
    it. Absent-by-nature is a value in the field, never a hole. (p151)"""
    if not (isinstance(f, dict) and all(k in f for k in _KIND_FIELDS)):
        return False
    # and it says something: every GGUF carries general.architecture, so a
    # record with neither an arch nor a block count is a file that was opened
    # and not understood - most often one still being copied in (p172)
    return bool(str(f.get("arch") or "").strip()) or int(f.get("blocks") or 0) > 0


def model_scan_failures():
    """Files the reader could not finish, with what was missing and why."""
    out = []
    with _KIND_LOCK:
        for store in (_KIND, _TKIND):
            for k, v in (_kind_map(store) or {}).items():
                if isinstance(v, dict) and v.get("_tries", 0) >= MODEL_SCAN_TRIES:
                    out.append({"file": k.split("|")[0], "tries": v.get("_tries", 0),
                                "missing": v.get("_missing", ""), "why": v.get("_why", "")})
    return out


def model_facts(path, book=None):
    """The cached form of the above - the same key as the kind cache, one entry."""
    try:
        stt = os.stat(path)
        key = _kind_key(path)
    except Exception:
        return _model_facts_read(path)
    # a file's identity does not say which book it is in, so both are asked
    with _KIND_LOCK:
        hit = _kind_map(_KIND).get(key) or _kind_map(_TKIND).get(key)
    # a remembered entry is used only if the read that made it FINISHED. One
    # that did not is re-read - up to MODEL_SCAN_TRIES times, after which it is
    # left alone and reported rather than retried at every scan for ever. The
    # count lives in the entry, so it survives a restart, and the identity key
    # carries size and mtime, so replacing the file clears it by itself. (p151)
    if (isinstance(hit, dict) and not _kind_stale(hit, stt)
            and (_facts_complete(hit)
                 or int(hit.get("_tries", 0)) >= MODEL_SCAN_TRIES)):
        return hit
    if isinstance(hit, dict) and _kind_stale(hit, stt):
        hit = None              # the file moved: what we remember is of another file
    # a read fails two ways - it raises, or it returns without every field.
    # Both are the same event to the ledger (p151)
    try:
        _before = os.stat(path)
        val = _model_facts_read(path)
        _after = os.stat(path)
        if (_before.st_size, int(_before.st_mtime)) != (_after.st_size, int(_after.st_mtime)):
            _MODEL_READ_WHY[os.path.abspath(path).lower()] = (
                "the file changed while it was being read - still being copied in?")
            val = {}
    except Exception:
        val = {}
    if not _facts_complete(val):
        # a file another program still has open is ARRIVING, not failing:
        # the attempt is not counted, and it is read again at the next look
        # (a menu opening, a page entered, the folder going quiet) (p178)
        _busy = file_in_use(path)
        _tries = int(hit.get("_tries", 0)) if isinstance(hit, dict) else 0
        if not _busy:
            _tries += 1
        val = dict(val)
        val["_tries"] = _tries
        val["_missing"] = ", ".join(k for k in _KIND_FIELDS if k not in val)
        val["_why"] = ("another program still has the file open - it is being "
                       "copied or moved in, and is read again once that finishes"
                       if _busy else
                       str(_MODEL_READ_WHY.get(os.path.abspath(path).lower())
                           or "the reader returned without these fields"))[:300]
        if _tries >= MODEL_SCAN_TRIES:
            log_error("panel",
                      "model scan gave up on %s after %d attempts - missing: %s - %s"
                      % (os.path.basename(path), _tries, val["_missing"], val["_why"]))
    # A caller may know which book this belongs in whatever the file turned out
    # to be: everything the TTS scan looks at is recorded in the TTS book, or a
    # stray file in that folder - an LTX quant, an LLM - is shown in the picker
    # while having no entry anywhere to explain why it reads as it does. The
    # book must cover the page that reads it. (p61)
    _store = _TKIND if book == "tts" else _kind_store(val)
    val = dict(val)
    val["_size"], val["_mtime"] = int(stt.st_size), int(stt.st_mtime)
    with _KIND_LOCK:
        # the other book cannot also hold this file: one entry, wherever it goes
        _kind_map(_TKIND if _store is _KIND else _KIND).pop(key, None)
        _kind_map(_store)[key] = val
        _store["dirty"] = True
    return val


def model_arch(path):
    """The architecture a file declares, lowercase, or "" if it will not say."""
    return str((model_facts(path) or {}).get("arch") or "") if path else ""


def _model_kind_read(path, meta=None, scan=None):
    """What a .gguf actually is: a chat model, a vision projector, or a draft model.

    The header is asked first. The name is only consulted when the header says nothing
    useful, because names are a convention and not a guarantee.
    """
    meta = gguf_meta(path) if meta is None else meta
    arch = str(meta.get("general.architecture") or "").lower()
    if arch == "clip" or meta.get("clip.has_vision_encoder") or meta.get("clip.has_audio_encoder"):
        return "vision"
    if is_draft_arch(arch) or any(is_draft_arch(str(k).split(".")[0]) for k in meta):
        return "draft"                            # it says so in its own header
    if scan is None:                              # what the file is built from
        scan = gguf_tensor_scan(path, meta.get(arch + ".block_count") or 0)
    sc = scan or {}
    if sc.get("nextn_last"):
        # the multi-token-prediction head llama.cpp itself looks for, at the LAST
        # block. With the blocks before it, this is a model that drafts for
        # itself; on its own, it is that head extracted into a drafter file.
        return "main" if sc.get("blk0") else "draft"
    if sc.get("mtp_names") or sc.get("eagle_names"):
        return "draft"                            # a head by any other tensor name
    if sc.get("vision") and not meta.get(arch + ".block_count"):
        return "vision"                           # a tower a model CARRIES is not
    low = os.path.basename(path).lower()          # a projector; only then, the name
    if "mmproj" in low or "-vision" in low or low.startswith("vision"):
        return "vision"
    # A LANGUAGE MODEL SAYS SO. Every one declares how many layers it has and
    # what context it was trained for; the owner's folder held a Flux diffusion
    # model, arch "flux", carrying neither - and "main" was the fallback, so it
    # was offered as something to load into llama.cpp as a chat model. The two
    # figures are the ones the card already prints as "N layers, Nk trained
    # context": a file that cannot fill that line is not a language model.
    # Named "other" rather than guessed at - what it IS is its own business.
    # (p120)
    if not meta.get(arch + ".block_count") and not meta.get(arch + ".context_length"):
        return "other"
    if "mtp" in re.split(r"[^a-z0-9]+", low) or "draft" in low or "eagle" in low:
        return "draft"
    return "main"

def list_models(cfg, quiet=False):
    d = cfg.get("settings", {}).get("modelsDir") or ""
    roots = []
    if d:
        roots.append(d)
    for x in cfg.get("launcherDirs", []):
        if x and x not in roots:
            roots.append(x)
    key = "|".join(roots)
    now = time.time()
    # the timer is the floor, not the rule: a folder whose contents changed is
    # re-read whatever the clock says, and one that did not is not re-read at
    # all until the timer runs out (p151)
    sig = _models_sig(roots)
    if _models_cache["dir"] == key and _models_cache.get("sig") == sig \
            and now - _models_cache["t"] < 300:
        return _models_cache["items"]
    _t_scan = time.monotonic()
    # HOW MANY THERE ARE, before reading any of them. A count that only goes up
    # says nothing about how much is left; the owner watched a folder scan with
    # no idea whether it was a second or a minute from finishing. Counting names
    # is a directory walk with no file opened, which is cheap beside reading 139
    # headers. (p129)
    _total = 0
    for _b in roots:
        if not os.path.isdir(_b):
            continue
        for _r, _d, _f in os.walk(_b):
            if _r[len(_b):].count(os.sep) > 3:
                _d[:] = []
                continue
            _total += len([_n for _n in _f if _n.lower().endswith(".gguf")])
    if not quiet:
        ready_mark("models", "working", "0 of %d read" % _total)
    items, seen = [], set()
    for base in roots:
        if not os.path.isdir(base):
            continue
        for root, dirs, files in os.walk(base):
            if root[len(base):].count(os.sep) > 3:
                dirs[:] = []
                continue
            for n in files:
                if not n.lower().endswith(".gguf"):
                    continue
                m = PART_RX.search(n)
                if m and m.group(1) != "00001":
                    continue
                full = os.path.join(root, n)
                if full.lower() in seen:
                    continue
                seen.add(full.lower())
                # said every time, because the page reads this while it happens -
                # the point is watching it move, not a number at the end (p129)
                if not quiet:
                    ready_mark("models", "working",
                               "%d of %d read" % (len(seen), _total))
                _f188 = model_facts(full)
                items.append({"path": full, "name": os.path.relpath(full, base),
                              "kind": _f188.get("kind", "main"),
                              "arch": _f188.get("arch", ""),
                              "archLabel": _f188.get("label", ""),
                              # the rule, not the cache: a record read before p181 kept
                              # the blank the old rule gave it, for ever (p183)
                              "archFamily": arch_family(_f188.get("arch", ""), os.path.basename(full)),
                              "blocks": _f188.get("blocks", 0),
                              "archCtx": _f188.get("ctx", 0),
                              # the two widths the picker compares before it lets a
                              # head be paired with a model it cannot attach to (h2)
                              # which KIND of speculation this file performs -
                              # the picker needs it to know whether the file
                              # attaches at all (v3.76 patch10)
                              "spec": _f188.get("spec", ""),
                              "embd": _f188.get("embd", 0),
                              "embdOut": _f188.get("embdOut", 0),
                              "mtpHead": bool(_f188.get("mtpHead")),
                              # opened and not understood - most often one
                              # still being copied in (p174)
                              "unread": not _facts_complete(_f188),
                              # the window a model was TRAINED with, straight
                              # from its header - reported, never set (p51)
                              "swa": int(_f188.get("swa") or 0),
                              # counted from the tensor names: a hybrid keeps a
                              # KV cache only for the layers that attend (p115)
                              "convLayers": int(_f188.get("convLayers") or 0),
                              "attnLayers": int(_f188.get("attnLayers") or 0),
                              "moe": bool(_f188.get("moe")),
                              "swaEvery": int(_f188.get("swaEvery") or 0),
                              "experts": int(_f188.get("experts") or 0),
                              "expertsUsed": int(_f188.get("expertsUsed") or 0),
                              "rope": str(_f188.get("rope") or ""),
                              "heads": int(_f188.get("heads") or 0),
                              "headsKv": int(_f188.get("headsKv") or 0),
                              "ffn": int(_f188.get("ffn") or 0),
                              "vocab": int(_f188.get("vocab") or 0),
                              "keyLen": int(_f188.get("keyLen") or 0),
                              "valLen": int(_f188.get("valLen") or 0),
                              "ropeBase": int(_f188.get("ropeBase") or 0),
                              "reasonTmpl": str(_f188.get("reasonTmpl") or ""),
                              # observed, not read: written by the proxy when a
                              # model reasoned with the switch off (p143)
                              "reasonObserved": str(_f188.get("reasonObserved") or ""),
                              "reasonObservedAt": str(_f188.get("reasonObservedAt") or ""),
                              "reasonSwitch": str(_f188.get("reasonSwitch") or "")})
    items.sort(key=lambda x: x["name"].lower())
    _gone172 = _kind_forget_missing(roots)
    _kind_flush()
    _kind_say_flush()          # outside every lock, once the scan is done (p123)
    if _gone172:
        panel_log("[models] %d remembered file%s no longer there - forgotten"
                  % (_gone172, "" if _gone172 == 1 else "s"))
    _took = (time.monotonic() - _t_scan) * 1000
    if _took > 1000:
        # also an observation: the scan finished, it just took a while
        log_warn("panel", "model folder scan: %dms for %d models (headers are read once "
                          "per file and remembered in model-kinds.json)" % (_took, len(items)))
    # WHAT THE LIST SAYS, not how long it is. The push and the menu-open answer
    # both keyed on the set of names, so a file re-read from "unreadable" to
    # "Qwen 3.5, 65 layers" - same name, same count - told nobody, and the
    # page kept its stale row until a restart. (p178)
    _prev_digest = _models_cache.get("digest")
    _digest = _models_digest(items)
    _models_cache.update(t=now, dir=key, items=items, sig=sig, digest=_digest)
    if _prev_digest is not None and _digest != _prev_digest:
        try:
            sse_notify("models", {"n": len(items)})
        except Exception:
            pass                # a page that is not listening is not a failure
    return items


def _models_digest(items):
    """One string that changes when anything the picker shows changes."""
    try:
        return hashlib.sha1(json.dumps(items, sort_keys=True, default=str)
                            .encode("utf-8")).hexdigest()
    except Exception:
        return str(len(items))

# ---------------------------------------------------------------- status / speeds
_ST_CACHE = {}
_ST_LOCK = threading.Lock()
_ST_TTL = 1.2
_ST_TTL_DOWN = 3.0  # a port that just sat out the probe is not up one poll later;
                    # on the owner's box two silent ports cost 2 x 0.35 s on EVERY
                    # state read - the down verdict now holds between clicks (p36)
_ST_WAIT = 0.35    # loopback: a live server accepts at once and a dead port refuses at
                   # once. Anything slower is a firewall/reservation dropping the SYN,
                   # and waiting a full second per server for that answer is pointless.
def _port_verdict(port, wait=1.5):
    """What a connection to a local port actually does. A closed port refuses at
    once (WSAECONNREFUSED); anything that waits out the clock is being filtered by
    something in the path, which is worth knowing before a server tries to bind it."""
    sk = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    sk.settimeout(wait)
    t0 = time.monotonic()
    try:
        sk.connect(("127.0.0.1", int(port)))
        return ("accepted", (time.monotonic() - t0) * 1000, 0)
    except ConnectionRefusedError:
        return ("refused", (time.monotonic() - t0) * 1000, 0)
    except socket.timeout:
        return ("no answer", (time.monotonic() - t0) * 1000, -1)
    except OSError as e:
        return ("error", (time.monotonic() - t0) * 1000, e.errno or -2)
    finally:
        try: sk.close()
        except Exception: pass

def _free_port():
    """A port nothing is listening on: bind it, note it, let it go."""
    sk = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    try:
        sk.bind(("127.0.0.1", 0))
        return sk.getsockname()[1]
    except Exception:
        return 0
    finally:
        try: sk.close()
        except Exception: pass

_PATH_RX = re.compile("(?:[A-Za-z]:" + chr(92)*2 + "|" + chr(92)*4 + ")[^" + chr(92) + "s" + chr(34) + chr(39) + "<>|]*")
def _mask_paths_in(text):
    """Strip anything path-shaped from text bound for a remote reader. Uses the same
    masker as the state payload so there is one rule, not two."""
    try:
        return _PATH_RX.sub(lambda m: _mask_path(m.group(0)), text)
    except Exception:
        # a masker that fails must not hand back the unmasked text: fail closed
        return "(hidden - could not be masked for a remote reader)"

def _probe_slot(port):
    """One loopback probe, resolver-free. socket.create_connection() and urlopen()
    both call getaddrinfo even for a numeric address, and on a machine with no
    default gateway that costs about a second EACH - three servers meant three
    seconds on every state read. A raw socket skips it; /health is spoken over the
    same connection instead of opening a second one."""
    sk = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    sk.settimeout(_ST_WAIT)
    try:
        sk.connect(("127.0.0.1", int(port)))       # connect(), not connect_ex: on
    except Exception:                              # Windows connect_ex sits out the
        try: sk.close()                            # timeout and answers WSAEWOULDBLOCK
        except Exception: pass                     # instead of reporting the refusal
        return {"state": "down"}
    try:
        sk.sendall(b"GET /health HTTP/1.1\r\nHost: 127.0.0.1\r\nConnection: close\r\n\r\n")
        head = sk.recv(64).decode("latin-1", "replace")
        if not head.startswith("HTTP/"):
            return {"state": "wedged"}
        code = int(head.split(" ", 2)[1])
        if code == 503:
            return {"state": "loading", "http": code}
        return {"state": "serving", "http": code}
    except Exception:
        return {"state": "wedged"}
    finally:
        try: sk.close()
        except Exception: pass

_PROPS = {}                      # port -> (asked_at, model_path, facts)
_PROPS_TTL = 60.0


def slot_props(port, want_path=""):
    """What llama.cpp says about the model IT loaded, from /props.

    The header reads elsewhere are a guess made from a substring; this is
    llama.cpp's own answer, parsed by its own Jinja engine. chat_template_caps
    carries supports_thinking, and the server only reports it true when --jinja
    is on - which no header can know. Only ever asked of a port that is already
    serving, so it costs nothing for a model nobody is running, and there is no
    way to ask it about one: /props describes the LOADED model. (p116)

    Same raw-socket shape as _probe_slot, for the same reason: getaddrinfo costs
    about a second per call on a machine with no default gateway.
    """
    port = int(port or 0)
    if not port:
        return {}
    now = time.time()
    hit = _PROPS.get(port)
    if hit and now - hit[0] < _PROPS_TTL and (not want_path or hit[1] == want_path):
        return hit[2]
    out = {}
    sk = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    sk.settimeout(_ST_WAIT)
    try:
        sk.connect(("127.0.0.1", port))
        sk.sendall(b"GET /props HTTP/1.1\r\nHost: 127.0.0.1\r\n"
                   b"Connection: close\r\n\r\n")
        buf = b""
        while len(buf) < (1 << 20):
            chunk = sk.recv(65536)
            if not chunk:
                break
            buf += chunk
        body = buf.split(b"\r\n\r\n", 1)[1] if b"\r\n\r\n" in buf else b""
        js = json.loads(body.decode("utf-8", "replace")) if body else {}
        caps = js.get("chat_template_caps") or {}
        mods = js.get("modalities") or {}
        out = {"loaded": str(js.get("model_path") or ""),
               # the server's OWN verdict, not a reading of the template text.
               # None when it did not answer: llama.cpp's caps map carries
               # supports_reasoning_effort and supports_preserve_reasoning, and
               # older builds carried supports_thinking - a build that sends
               # none of them has said nothing, which is not the same as no.
               "thinks": (bool(caps.get("supports_thinking"))
                          if "supports_thinking" in caps else None),
               "keepsReasoning": bool(caps.get("supports_preserve_reasoning")),
               "tools": bool(caps.get("supports_tools")),
               "vision": bool(mods.get("vision")),
               "audio": bool(mods.get("audio")),
               "slots": int(js.get("total_slots") or 0),
               "build": str(js.get("build_info") or "")}
    except Exception:
        out = {}
    finally:
        try:
            sk.close()
        except Exception:
            pass
    _PROPS[port] = (now, want_path, out)
    return out


def prime_slot_status(ports):
    """Probe every server at once. Serial probes cost N x the timeout on machines
    where a closed port is dropped rather than refused."""
    todo = []
    now = time.time()
    with _ST_LOCK:
        for p0 in ports:
            if not p0:
                continue
            hit = _ST_CACHE.get(int(p0))
            if not (hit and now - hit[0] < _ST_TTL):
                todo.append(int(p0))
    if not todo:
        return
    ths = [threading.Thread(target=slot_status, args=(x,), daemon=True) for x in todo]
    for t in ths:
        t.start()
    for t in ths:
        t.join(timeout=_ST_WAIT + 0.4)

def slot_status(port):
    if not port:
        return {"state": "unknown"}
    key = int(port)
    with _ST_LOCK:
        hit = _ST_CACHE.get(key)
        if hit:
            _ttl = (_ST_TTL_DOWN if hit[1].get("state") in ("down", "wedged")
                    else _ST_TTL)
            if time.time() - hit[0] < _ttl:
                return dict(hit[1])
    out = _probe_slot(key)
    with _ST_LOCK:
        _ST_CACHE[key] = (time.time(), dict(out))
    return dict(out)

NUM = r"([0-9]+(?:\.[0-9]+)?)"
PP_RX = [re.compile(r"prompt eval time[^\n]*?\(\s*" + NUM + r"\s*tokens per second", re.I),
         re.compile(r"prompt processing[^\n]*?" + NUM + r"\s*t/s", re.I)]
TG_RX = [re.compile(r"(?<!prompt )eval time[^\n]*?\(\s*" + NUM + r"\s*tokens per second", re.I),
         re.compile(r"token generation[^\n]*?" + NUM + r"\s*t/s", re.I)]
def speeds_for_slot(slot_id, ld):
    files = sorted(glob.glob(os.path.join(ld, "srv_%s_*.log" % glob.escape(slot_id))),
                   key=os.path.getmtime, reverse=True)
    if not files:
        return None
    try:
        with open(files[0], "rb") as f:
            f.seek(0, 2)
            f.seek(max(0, f.tell() - 65536))
            text = ANSI_RX.sub("", f.read().decode("utf-8", errors="ignore"))
    except Exception:
        return None
    def avg(rxs):
        vals = []
        for rx in rxs:
            vals += [float(v) for v in rx.findall(text)]
        vals = vals[-5:]
        return round(sum(vals) / len(vals), 1) if vals else None
    pp, tg = avg(PP_RX), avg(TG_RX)
    if pp is None and tg is None:
        return None
    return {"pp": pp, "tg": tg}

def api_network_info(body=None):
    panel_ip = (load_config().get("settings", {}) or {}).get("panelIp") or ""
    host_ip = panel_ip or primary_lan_ip()
    return {
        "mode": net_mode(),
        "devMode": dev_mode(),
        "lanIp": host_ip,
        "port": PORT,
        "lanUrl": ("http://%s:%d/" % (host_ip, PORT)) if host_ip else "",
        "networkDown": network_is_down(),
        "usingPanelIp": bool(panel_ip),
    }

_LAUNCH_SAID = {}            # slot id -> the log whose fault has been recorded (p178)


def api_state():
    cfg  = load_config()
    hist = load_json(HISTORY, []) or []
    ld   = log_dir(cfg)
    def build(s):
        script = s.get("script") or ""
        actual = (parse_ps1_port(script) if script else None) or s.get("port")
        st = slot_status(actual)
        # a card that never turns green used to say nothing at all about why
        # (patch25)
        if st.get("state") != "serving":
            _lf25 = sorted(glob.glob(os.path.join(ld, "srv_%s_*.log"
                                                  % glob.escape(str(s.get("id") or "")))),
                           key=os.path.getmtime, reverse=True)
            if _lf25:
                _flt = slot_launch_fault(_lf25[0], st.get("state", ""))
                if _flt:
                    st = dict(st); st["fault"] = _flt
                    # said once per launch: the card shows it, and Log >
                    # Errors is where a reader looks for it later (p178)
                    # a log the last session left behind is old and quiet by
                    # definition; only a log written THIS session can say a
                    # launch did not finish (p186: fourteen at start-up)
                    if _LAUNCH_SAID.get(s.get("id")) != _lf25[0] and os.path.getmtime(_lf25[0]) >= PANEL_T0:
                        _LAUNCH_SAID[s.get("id")] = _lf25[0]
                        log_error("slot " + str(s.get("title") or s.get("id") or ""),
                                  "launch did not finish: %s" % _flt)
        # llama.cpp's own account of the model IT loaded, and ONLY when one is
        # loaded. This is the authoritative half: the header reads elsewhere are
        # a guess made from a substring, while chat_template_caps is the verdict
        # of llama.cpp's own Jinja parser - and it reports supports_thinking as
        # false when --jinja is off, which no reading of a file could know. (p116)
        if st.get("state") == "serving":
            _pr = slot_props(actual, str((s.get("params") or {}).get("model") or ""))
            if _pr:
                st = dict(st)
                st["props"] = _pr
        spd = speeds_for_slot(s.get("id"), ld) if st["state"] in ("serving", "loading") else None
        scan_slot_errors(s.get("id"), s.get("label", "?"), ld)
        last = next((h for h in hist if h.get("slotId") == s.get("id")), None)
        return {**s, "actualPort": actual, "status": st, "speeds": spd, "lastLaunch": last,
                "model": (parse_ps1_model(script) if script else ""),
                # "" is a language model; "vision" and "draft" are not, and neither can
                # answer a chat request. Read once per file and remembered.
                "modelKind": (model_kind(parse_ps1_model(script)) if script else ""),
                "scriptExists": bool(script) and os.path.isfile(script),
                "gpuId": s.get("gpuId", ""), "gpu": s.get("gpu", ""),
                "params": {k: v for k, v in (s.get("params", {}) or {}).items() if k != "prevCustom"}}
    with ThreadPoolExecutor(max_workers=8) as ex:
        slots = list(ex.map(build, cfg.get("slots", [])))
    routing = [{"id": s.get("id"), "label": s.get("label"), "port": s.get("port"),
                "gpu": s.get("gpu", ""), "gpuId": s.get("gpuId", ""), "samplers": (parse_ps1_samplers(s["script"]) if s.get("script") else {}), "logSamplers": (parse_log_samplers(s.get("id"), log_dir(cfg)) if s.get("script") else {}), "reasoning": ((parse_ps1_reasoning(s["script"]) or parse_log_reasoning(s.get("id"), log_dir(cfg))) if s.get("script") else ""),
                "model": (parse_ps1_model(s["script"]) if s.get("script") else ""), "hasScript": bool(s.get("script")), "providers": [
                    {"diaryGrammar": p.get("diaryGrammar", False), **p, "stats": PROXY.stats.get(p.get("id")),
                     "obsSamplers": PROXY.observed.get(p.get("id")) or {},
                     "srvSamplers": (parse_log_samplers(s.get("id"), log_dir(cfg)) if s.get("script") else {}),
                     "samplerSource": (p.get("samplerSource") or "server"),
                     "detectSN": bool(p.get("detectSN")),
                     "panelOwned": p.get("id") in PANEL_PROV_IDS,
                     "cache": bool(p.get("cache")),
                     "cacheSlot": cached_slot_map(s).get(str(p.get("id") or "")),
                     "enabled": (panel_prov_on(p.get("id"), cfg.get("settings", {}))
                                 if p.get("id") in PANEL_PROV_IDS
                                 else p.get("enabled") is not False),
                     "samplerOverrides": {k: v for k, v in (p.get("samplerOverrides") or {}).items() if str(v).strip() != ""}} for p in (s.get("providers") or [])]}
               for s in cfg.get("slots", [])]
    # the chosen TTS, and what it cannot perform - read once, because every
    # board and both default prompts below answer to it (p54)
    _pk54 = tts_pack(cfg)
    _unp54 = tts_unperformed(_pk54)
    return {"version": APP_VER_UI, "build": BUILD_ID, "stack": STACK,
            "paramDefs": [{"key": k, "label": lab, "kind": kind, "def": dv, "opt": o,
                           "flag": f, "ref": ref, "group": PARAM_GROUP.get(k, "Other"),
                           "caution": PARAM_CAUTION.get(k) or {}}
                          for (k, lab, kind, dv, o, f, ref) in SERVER_PARAMS],
            # the order the card lays the groups out in - the launcher writer already
            # groups by the same names, so a heading on the card names a block of flags
            # you can find in the .ps1
            "paramGroups": list(PARAM_GROUP_ORDER),
            "elevated": is_admin(), "slots": slots, "settings": cfg.get("settings", {}),
            "creatorSlots": cfg.get("creatorSlots", []), "routing": routing,
            "unallocated": cfg.get("unallocatedProviders", []) or [],
            "gpus": cfg.get("gpus", []), "panelPort": PORT,
            "profiles": _profile_names(),
            "llamaOk": bool(cfg.get("settings", {}).get("llamacppPath"))
                       and os.path.isfile(os.path.join(cfg.get("settings", {}).get("llamacppPath", ""), "llama-server.exe")),
            "listening": sorted(PROXY._servers.keys()), "ttsWrap": TTSW.state(),
            "higgsInstall": dict(HIGGS_INSTALL),
            "higgsFound": higgs_present(cfg),
            "ttsPack": tts_pack_view(cfg),
            "ttsHave": tts_packs_present(cfg),
            "ttsPacks": [{"fam": p["fam"], "label": p["label"],
                          "gb": p["gb"], "task": p["task"],
                          # what the guide's download line needs: the repo, the
                          # file in it, the folder it lands in, the licence (p147)
                          "repo": p.get("repo", ""), "path": p.get("path", ""),
                          "dir": p.get("dir", ""), "licence": p.get("licence", ""),
                          "note": p.get("note", ""),
                          "wip": p["fam"] not in TTS_SETTLED,
                          # from the cache only - the state path is polled and
                          # must not wait on a repo listing (p109)
                          "range": tts_size_range(p)}
                         for p in TTS_PACKS.values()],
            # what a proxy engine loads elsewhere: read from the repo that
            # publishes it, or the stated fallback until that is read (p114)
            "ttsProxy": {k: {"label": v["label"], "size": tts_proxy_size(k)}
                         for k, v in TTS_PROXY_BASE.items()},
            # is llama.cpp actually there? The button said "Install" for a
            # hand-placed copy because it only knew what the panel had installed
            # itself, which for most people is nothing. (p73)
            "llamaHave": os.path.isfile(llama_exe(cfg)),
            "llamaLines": [dict(x) for x in LLAMA_LINES],
            "ttsServer": tts_server_status(cfg),
            "updGuard": {"llama": llama_servers_up(cfg), "tts": tts_server_up(cfg)},   # each updater's own servers (p195)
            # WHAT IS AND IS NOT READY, on the one path everything already
            # reads. Anything that would otherwise invent an explanation for
            # missing data can ask instead. (p128)
            "ready": ready_state(),
            # WHAT THE HOST KNOWS ABOUT ITS OWN VERSION, so a remote viewer can
            # show the same colour the host shows: green for the newest release,
            # yellow for one that is behind. Read from the cache the host's own
            # check filled - never fetched here, so building a state never asks
            # github. A viewer cannot act on it; that stays host-only. (p140)
            "upd": _upd_summary(),
            # the audio.cpp floor, so the guide prints the constant rather than a
            # copy of it (p147)
            "acppMin": "%d.%d" % ACPP_MIN_VER,
            "speechTitles": list(SPEECH_TITLES),
            # shown in the prompt editor so "the built-in wording" is not a mystery -
            # as it CURRENTLY reads, clicked-off tags and all
            # the tab compares this against the tag baked into its own page and
            # reloads itself on a mismatch - a terminal left open across panel
            # updates was running week-old JS, and every fix "changed nothing"
            "app": APP_RELEASE_TAG,
            "defaultPtiPrompt": tts_tag_prompt("", tags_off(cfg.get("settings", {}),
                                                          pack=_pk54)),
            "defaultPmePrompt": mood_prompt(mood_count(cfg.get("settings", {})), "",
                                            tags_off(cfg.get("settings", {}),
                                                     pack=_pk54)),
            # the vocabulary the Audio Tags buttons draw, grouped as offered
            # the boards draw what the CHOSEN TTS performs. A switch for a tag
            # that will be removed before synthesis is a switch that does
            # nothing, and the user cannot tell which kind they are looking at
            "tagOffer": [[label, [w for w in words
                                  if w.upper() not in _unp54]]
                         for label, words in TAG_OFFER],
            "tagUnperformed": sorted(_unp54),
            # every character the panel has met, so a terminal paints names from the
            # ledger instead of each painter hard-coding the few it knows (v3.76 h1)
            "cast": sorted({n for n in list(_spk_voices.values()) + list(_spk_known)
                            if n} | ({_spk_player[0]} if _spk_player[0] else set())),
            "launchers": list_launchers(cfg), "history": hist[:50]}

def is_admin():
    try:
        return bool(ctypes.windll.shell32.IsUserAnAdmin())
    except Exception:
        return False

# ---------------------------------------------------------------- fleet plumbing
# Windows: a console program spawned from a process that has NO console gets a brand
# new, VISIBLE one. python.exe started with CREATE_NO_WINDOW still had a console - just
# hidden - and children inherited it silently. pythonw.exe, preferred since v3.72
# patch16 so that nothing had to be started hidden, has no console at all, so every
# pwsh and nvidia-smi call began popping a window on screen. Suppress it explicitly on
# every child rather than relying on inheriting somebody else's hidden console.
NOWIN = {"creationflags": 0x08000000} if os.name == "nt" else {}   # CREATE_NO_WINDOW


FLEET_ACT = {"n": 0}           # fleet launches or stops in flight (p195)


def llama_servers_up(cfg=None):
    """The llama.cpp servers that are starting, serving or stopping - each of them
    holds the folder's DLLs, and the owner's own self-test proved a held DLL
    cannot be replaced or renamed away. Names, empty when none. (p195)"""
    up = []
    try:
        if FLEET_ACT["n"] > 0:
            up.append("a launch or stop still in progress")
        cfg = cfg or load_config()
        for s in (cfg.get("slots") or []):
            port = (s.get("params") or {}).get("port") or s.get("port")
            try:
                st = slot_status(int(port)) if port else {"state": "unknown"}
            except Exception:
                st = {"state": "unknown"}
            if st.get("state") in ("loading", "serving", "wedged"):
                up.append("%s (%s)" % (s.get("name") or s.get("id") or "slot", st.get("state")))
    except Exception:
        pass                # a guard that cannot look answers "none" and the install proceeds as before
    return up


def tts_server_up(cfg=None):
    """The TTS server if it is starting, serving or stopping - it holds audio.cpp
    and its model. One name, or none. (p195)"""
    try:
        st = tts_server_status(cfg or load_config())
        if st.get("stopping"):
            return ["the TTS server (stopping)"]
        if st.get("state") in ("loading", "serving", "wedged"):
            return ["the TTS server (%s)" % st.get("state")]
        if st.get("pid"):
            return ["the TTS server (starting)"]
    except Exception:
        pass                # as above
    return []


def run_fleet(extra):
    cmd = ["pwsh", "-NoProfile", "-ExecutionPolicy", "Bypass", "-File", FLEET_PS1] + extra
    try:
        FLEET_ACT["n"] += 1
        try:
            p = subprocess.run(cmd, capture_output=True, text=True, timeout=300, **NOWIN)
        finally:
            FLEET_ACT["n"] -= 1
        log = (p.stdout or "")
        if (p.stderr or "").strip():
            log += "\n" + p.stderr
        for ln in log.splitlines():
            if ERR_RX.search(ln) and not BENIGN_RX.search(ln):
                log_error("fleet", ln)
        return log.strip() or "(no output)"
    except subprocess.TimeoutExpired:
        return "ERROR: launch-llm-fleet.ps1 timed out"
    except FileNotFoundError:
        return "ERROR: pwsh not found on PATH"

def api_action(body, mode):
    sid = body.get("slot", "")
    if mode == "launch":
        SLOT_LAUNCH_AT[sid] = time.time()   # the watermark the report answers to (p43)
    args = ["-Slot", sid] + (["-Force"] if mode == "launch" else ["-Stop"])
    with _ST_LOCK:
        _ST_CACHE.clear()          # a click changes the world: the next state
                                   # read asks the ports, not the cache (p36)
    panel_log("[panel] %s %s" % (mode, sid))
    if mode == "launch":
        try:
            _cfg = load_config()
            _s = next((x for x in _cfg.get("slots", []) if x.get("id") == sid), None)
            if _s and (_s.get("params") or {}).get("model"):
                # regen_slot_script returns a PATH for a generated launcher and a
                # {"changed": [...]} dict for one edited in place. Only a dict carrying
                # "error" is a failure - testing isinstance skipped the save for every
                # hand-written launcher.
                _r = regen_slot_script(_cfg, _s)
                if not (isinstance(_r, dict) and _r.get("error")):
                    save_config(_cfg)
            if _s:
                # Say it BEFORE the engine does. llama.cpp accepts a head whose width
                # its host cannot receive - the vocabularies match - and then stops at
                # GGML_ASSERT(ggml_can_mul_mat) with no mention of which of the two
                # files was wrong. The card already colours the pairing yellow; this
                # is for the launch that starts anyway, from a hand-edited config or a
                # launcher written earlier, so the reason sits directly above the
                # crash instead of nowhere. It WARNS and launches: the panel does not
                # countermand a chosen setting. (v3.76 hotfix2)
                _pp = _s.get("params") or {}
                _host = model_facts(_pp.get("model") or "") if _pp.get("model") else None
                for _k9, _lab9 in (("draft", "draft model"), ("vision", "vision projector")):
                    _v9 = _pp.get(_k9) or ""
                    if not _v9 or _v9 in ("N/A", "@builtin-mtp") or not _host:
                        continue
                    _why9 = model_fit(_host, model_facts(_v9))
                    if _why9:
                        panel_log("[panel] %s: the %s does not fit this model - %s. "
                                  "llama.cpp will accept the pair and then stop at "
                                  "GGML_ASSERT(ggml_can_mul_mat)." % (sid, _lab9, _why9))
                _up = (parse_ps1_port(_s.get("script") or "") if _s.get("script") else None) or _s.get("port")
                if _up: PROXY.note_load(_up)
        except Exception: pass
    out = {"log": run_fleet(args)}
    sse_notify("state")
    return out

def api_stats_reset(body):
    PROXY.sstats.clear(); PROXY.pstats.clear()
    return {"ok": True}

CLIENTS = {}
LIFE = {"ever": False, "empty_since": None, "exiting": False}
import queue as _queue
SSE_CLIENTS = {}                 # queue -> scope ("host" | "remote"): a notify
_REQ_SCOPE = threading.local()   # can address one side of the glass alone (p37)
SSE_SEQ = {"n": 0}   # bumps on every notify; the heartbeat echoes it so the page can spot a dead stream
def sse_notify(kind, extra=None, scope=None):
    SSE_SEQ["n"] += 1
    msg = json.dumps({"t": kind, "seq": SSE_SEQ["n"], **(extra or {})})
    for q, sc in list(SSE_CLIENTS.items()):
        if scope is not None and sc != scope:
            continue
        try: q.put_nowait(msg)
        except Exception: pass

_status_sig = {"v": None}
_tail_sig = {"v": None, "path": None}

def tail_watch_sig(cfg=None):
    """Signature of a log the panel does NOT write itself.

    The proxy and thinking logs are written here, so report() can notify directly.
    tts.log is written by a separate process, so nothing tells the panel it moved and
    its terminal would sit still until some unrelated event happened to fire. mtime
    plus size, because a same-second append can leave mtime unchanged on Windows.
    """
    try:
        st = os.stat(os.path.join(log_dir(cfg), TTS_LOG_NAME))
        return (st.st_mtime_ns, st.st_size)
    except Exception:
        return None

def status_watch_loop():
    n = 0
    while True:
        time.sleep(1)
        n += 1
        try:
            if not SSE_CLIENTS:
                continue
            # one stat per second, and only while a page is actually watching
            sig = tail_watch_sig()
            if sig != _tail_sig["v"]:
                _tail_sig["v"] = sig
                sse_notify("tail")
            if n % 3:
                continue          # server status stays on its original 3s cadence
            cfg = load_config()
            sig = {}
            with ThreadPoolExecutor(max_workers=6) as ex:
                def one(s):
                    script = s.get("script") or ""
                    ap = (parse_ps1_port(script) if script else None) or s.get("port")
                    st = slot_status(ap)
                    return s.get("id"), "%s/%s" % (st.get("state"), st.get("http", ""))
                for k, v in ex.map(one, cfg.get("slots", [])):
                    sig[k] = v
            _cfgd = cfg.get("settings", {})
            if (_cfgd.get("ttsServerExe") or _cfgd.get("ttsAcppDir") or "").strip():
                _t = slot_status(tts_server_port(cfg))     # only when TTS is configured
                sig["_tts"] = "%s/%s" % (_t.get("state"), _t.get("http", ""))
                if _t.get("state") == "serving" and not TTS_PROC.get("said_ready"):
                    TTS_PROC["said_ready"] = True
                    TTSW.log("\u2705 %s ready for voice synthesis" % tts_engine_label(cfg))
                    TTSW.segment_open()
                elif _t.get("state") != "serving":
                    TTS_PROC["said_ready"] = False
            if sig != _status_sig["v"]:
                _status_sig["v"] = sig
                sse_notify("state")
        except Exception:
            pass

def sweep_launcher_shells():
    """Close any launcher shell left over after the servers have gone.

    Returns the number closed. Only shells whose command line mentions this
    install folder are touched, so nothing else the user is running is at risk.
    """
    try:
        root = STACK.replace("'", "''")
        ps = ("$me=$PID; $root='" + root + "'; $n=0; "
              "Get-CimInstance Win32_Process -Filter \"Name='pwsh.exe'\" -ErrorAction SilentlyContinue | "
              "Where-Object { $_.ProcessId -ne $me -and $_.CommandLine -and "
              "$_.CommandLine -like ('*' + $root + '*') } | "
              "ForEach-Object { $n++; Stop-Process -Id $_.ProcessId -Force -ErrorAction SilentlyContinue }; "
              "Write-Output $n")
        p = subprocess.run(["pwsh", "-NoProfile", "-ExecutionPolicy", "Bypass", "-Command", ps],
                           **NOWIN,
                           capture_output=True, text=True, timeout=30)
        try:
            return int((p.stdout or "0").strip().splitlines()[-1])
        except Exception:
            return 0
    except Exception as e:
        log_error("exit", e)
        return 0

def clear_download_mark():
    """Drop Windows' "came from the internet" mark from our own folder.

    It is what makes SmartScreen warn, and it lingers on every extracted file. Clearing
    it here means there is nothing extra for anyone to run. Ours only - nothing outside
    the install folder is touched.
    """
    if os.name != "nt":
        return
    try:
        for root, _dirs, files in os.walk(STACK):
            for f in files:
                try:
                    os.remove(os.path.join(root, f) + ":Zone.Identifier")
                except OSError:
                    pass
    except Exception:
        pass

def full_exit(reason, kill_servers=True):
    if LIFE["exiting"]: return
    LIFE["exiting"] = True
    panel_log("[panel] EXIT (%s)%s" % (reason, "" if kill_servers else " - servers left running"))
    if kill_servers:
        try:
            # the SAME stop the TTS page's Stop button runs, in the same order: the
            # handled process first, then whatever owns the TTS port - which is what
            # catches a server a PREVIOUS panel run started, exactly as the button
            # already did. patch123 wrote a second discovery (a command-line sweep)
            # instead of calling the one that existed, and its PowerShell quoting
            # emitted rows no parser matched - a second copy of a rule, drifted, on
            # its first day. TTS first: on a closing console this handler has ~5
            # seconds, and the fleet's own -Stop below can eat all of them.
            stop_tts_server(reason)
            _kill_port_owner(tts_server_port())
            tts_clock_release("panel exit")
        except Exception:
            pass
        out = run_fleet(["-Stop"])
        panel_log(out)
        n = sweep_launcher_shells()          # -Stop misses shells with no live port
        if n:
            panel_log("[panel] closed %d leftover launcher window(s)" % n)
    try:
        for srv in list(PROXY._servers.values()):
            import threading as _th
            _th.Thread(target=srv.shutdown, daemon=True).start()
        if getattr(TTSW, "_srv", None):
            import threading as _th2
            _th2.Thread(target=TTSW._srv.shutdown, daemon=True).start()
    except Exception: pass
    time.sleep(0.5)
    os._exit(0)

def watchdog_loop():
    import threading
    while True:
        time.sleep(3)
        try:
            cfg_on = True                      # always shut the fleet down with the panel
            now = time.time()
            for uid in [u for u, ts in CLIENTS.items() if now - ts > 150]:
                CLIENTS.pop(uid, None)
            if CLIENTS:
                LIFE["ever"] = True
                LIFE["empty_since"] = None
            elif LIFE["ever"] and cfg_on:
                if LIFE["empty_since"] is None:
                    LIFE["empty_since"] = now
                elif now - LIFE["empty_since"] > 8:
                    threading.Thread(target=full_exit, args=("browser closed",), daemon=True).start()
                    return
        except Exception as e:
            log_error("watchdog", e)

def api_terminate(body):
    panel_log("[panel] terminate all servers")
    stop_tts_server("terminate button", wait=False)      # a panel-started TTS server counts as one
    return {"log": _stamp_log(run_fleet(["-Stop"]))}

def api_exit(body):
    import threading
    threading.Timer(0.6, full_exit, args=("exit button",)).start()
    return {"ok": True, "msg": "shutting down"}

def api_handoff(body):
    import threading
    threading.Timer(0.3, full_exit, args=("handoff to new instance", False)).start()
    return {"ok": True}

AIB_VENDORS = {0x1043: "ASUS", 0x19DA: "ZOTAC", 0x1462: "MSI", 0x1458: "GIGABYTE",
               0x3842: "EVGA", 0x196E: "PNY", 0x1569: "PALIT", 0x10B0: "GAINWARD",
               0x7377: "COLORFUL", 0x1B4C: "GALAX/KFA2", 0x1849: "ASROCK", 0x10DE: "NVIDIA FE"}
def brand_from_sub(sub):
    try:
        v = int(str(sub).strip(), 16)
    except Exception:
        return ""
    lo, hi = v & 0xFFFF, (v >> 16) & 0xFFFF
    if lo in AIB_VENDORS:
        return AIB_VENDORS[lo]
    if hi in AIB_VENDORS:
        return AIB_VENDORS[hi]
    return "sub 0x%04X" % lo if lo else ""

def gpu_short(g):
    name = (g.get("name") or "GPU").replace("NVIDIA GeForce ", "").replace("NVIDIA ", "")
    b = g.get("brand") or ""
    return (b + " " + name).strip()

def apply_auto_names(cfg):
    gpus = {g.get("id"): g for g in cfg.get("gpus", [])}
    per = {}
    for s in cfg.get("slots", []):
        if s.get("autoName") and s.get("gpuId") in gpus:
            per.setdefault(s["gpuId"], []).append(s)
    n = 0
    for gid, ss in per.items():
        # Server (N): <gpu>, numbered across the fleet in slot order, and the gpu
        # part clamped so the card's first row cannot be pushed into a second
        gpu = gpu_short(gpus[gid])
        if len(gpu) > 24:
            gpu = gpu[:23].rstrip() + "\u2026"
        for s in ss:
            n += 1
            s["label"] = "Server %d: %s" % (n, gpu)

def api_gpu_edit(body):
    cfg = load_config()
    for g in cfg.get("gpus", []):
        if g.get("id") == body.get("id"):
            if "enabled" in body:
                g["enabled"] = bool(body["enabled"]) if not isinstance(body["enabled"], str) else body["enabled"].lower() in ("1", "true", "on")
            save_config(cfg); PROXY.sync()
            return {"ok": True}
    return {"error": "unknown GPU"}

def api_detect_gpus(body=None):
    try:
        p = subprocess.run(["nvidia-smi", "--query-gpu=index,name,uuid,memory.total,pci.sub_device_id",
                            "--format=csv,noheader"], capture_output=True, text=True,
                           timeout=15, **NOWIN)
        rows = [r.strip() for r in (p.stdout or "").splitlines() if r.strip()]
        if p.returncode != 0 or not rows:
            return {"error": "nvidia-smi returned nothing (%s)" % (p.stderr or "").strip()[:120]}
    except Exception as e:
        return {"error": "nvidia-smi failed: %s" % e}
    cfg = load_config()
    gl = cfg.setdefault("gpus", [])
    byu = {g.get("uuid"): g for g in gl}
    used = {g.get("id") for g in gl}
    for r in rows:
        parts = [x.strip() for x in r.split(",")]
        if len(parts) < 3:
            continue
        idx, name, uuid = parts[0], parts[1], parts[2]
        mem = parts[3] if len(parts) > 3 else ""
        sub = parts[4] if len(parts) > 4 else ""
        brand = brand_from_sub(sub)
        if uuid in byu:
            byu[uuid].update(index=idx, name=name, mem=mem, sub=sub, brand=brand)
        else:
            n = 0
            while "gpu%d" % n in used:
                n += 1
            used.add("gpu%d" % n)
            gl.append({"id": "gpu%d" % n, "uuid": uuid, "index": idx, "name": name,
                       "mem": mem, "sub": sub, "brand": brand})
    for s in cfg.get("slots", []):   # auto-link by legacy gpu-name-substring tag
        if not s.get("gpuId") and s.get("gpu"):
            hits = [g for g in gl if s["gpu"].lower() in (g.get("name") or "").lower()]
            if len(hits) == 1:
                s["gpuId"] = hits[0]["id"]
    apply_auto_names(cfg)
    save_config(cfg)
    PROXY.sync()
    panel_log("[panel] GPUs detected: %s" % ", ".join(g["name"] for g in gl))
    return {"gpus": gl}

def api_open_file(body):
    cfg = load_config()
    path = os.path.abspath(body.get("path", ""))
    if not _within(path, _all_roots(cfg)):
        return {"error": "path outside the allowed folders"}
    if os.path.splitext(path)[1].lower() in _EXE_EXTS:
        return {"error": "refusing to open an executable file"}
    if not os.path.isfile(path):
        return {"error": "file not found"}
    try:
        os.startfile(path)
        return {"ok": True}
    except AttributeError:
        return {"error": "open-file is Windows-only"}
    except Exception as e:
        return {"error": str(e)}

